@dataclass
class Config(ConfigDefaults):
    """Dynamische Konfiguration, die von ConfigDefaults erbt."""

    _base_chunk_duration: int = ConfigDefaults.BASE_CHUNK_DURATION
    CHUNK_OVERLAP: float = ConfigDefaults.CHUNK_OVERLAP
    MIN_CHUNK_DURATION: int = ConfigDefaults.MIN_CHUNK_DURATION
    MAX_CHUNK_DURATION: int = ConfigDefaults.MAX_CHUNK_DURATION
    LANGUAGE_VAD: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.LANGUAGE_VAD.copy()
    )
    _actual_chunk_duration: float = field(init=False, default=float(ConfigDefaults.BASE_CHUNK_DURATION))

    AUDIO_FILTER: str = "aresample=16000"
    LANGUAGE_FILTERS: Dict[str, str] = field(
        default_factory=lambda: {k: "aresample=16000" for k in ConfigDefaults.LANGUAGE_VAD}
    )
    FILTER_PROFILES: Dict[str, str] = field(
        default_factory=lambda: {
            "transcription": "aresample=16000",
            "translation": "aresample=16000",
            "realtime": "aresample=16000",
            "noisy": "aresample=16000,volume=2.5,highpass=f=150,lowpass=f=3000",
            "music": "aresample=16000",
            "podcast": "aresample=16000",
        }
    )

    YOUTUBE_HEADERS: Dict[str, str] = field(
        default_factory=lambda: ConfigDefaults.YOUTUBE_HEADERS.copy()
    )
    PLATFORM_CONFIG: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.PLATFORM_CONFIG.copy()
    )

    AUDIO_ENHANCEMENT_ENABLED: bool = False          # überschreibt ConfigDefaults.TRUE
    MIN_RMS_THRESHOLD: float = ConfigDefaults.MIN_RMS_THRESHOLD
    TARGET_RMS: float = ConfigDefaults.TARGET_RMS
    MAX_GAIN: float = ConfigDefaults.MAX_GAIN
    CLIPPING_THRESHOLD: float = ConfigDefaults.CLIPPING_THRESHOLD

    DUPLICATE_CHECK_ENABLED: bool = False
    RECENT_TRANSCRIPTIONS_SIZE: int = ConfigDefaults.RECENT_TRANSCRIPTIONS_SIZE
    MIN_TEXT_LENGTH: int = ConfigDefaults.MIN_TEXT_LENGTH
    MIN_UNIQUE_WORDS_RATIO: float = ConfigDefaults.MIN_UNIQUE_WORDS_RATIO

    SUBTITLE_BUFFER_SIZE: int = ConfigDefaults.SUBTITLE_BUFFER_SIZE
    ENABLE_TIMED_TRANSCRIPTIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSCRIPTIONS
    ENABLE_TIMED_TRANSLATIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSLATIONS

    ENABLE_DEBUG_LOGGING: bool = ConfigDefaults.ENABLE_DEBUG_LOGGING
    LOG_CHUNK_PROCESSING: bool = ConfigDefaults.LOG_CHUNK_PROCESSING
    LOG_AUDIO_STATS: bool = ConfigDefaults.LOG_AUDIO_STATS
    LOG_PERFORMANCE: bool = ConfigDefaults.LOG_PERFORMANCE
    LOG_STREAM_EVENTS: bool = ConfigDefaults.LOG_STREAM_EVENTS
    PERFORMANCE_LOG_INTERVAL: int = ConfigDefaults.PERFORMANCE_LOG_INTERVAL

    MAX_CACHE_SIZE_MB: int = ConfigDefaults.MAX_CACHE_SIZE_MB
    CACHE_ENABLED: bool = ConfigDefaults.CACHE_ENABLED

    WHISPER_MODELS: List[str] = field(default_factory=lambda: ConfigDefaults.WHISPER_MODELS.copy())

    @property
    def CHUNK_DURATION(self) -> float:
        return self._actual_chunk_duration

    @CHUNK_DURATION.setter
    def CHUNK_DURATION(self, value: float) -> None:
        if self.MIN_CHUNK_DURATION <= value <= self.MAX_CHUNK_DURATION:
            self._actual_chunk_duration = float(value)
        else:
            logger.warning(
                f"⚠️ Chunk duration {value}s out of range, clamping to [{self.MIN_CHUNK_DURATION}, {self.MAX_CHUNK_DURATION}]"
            )
            self._actual_chunk_duration = max(
                self.MIN_CHUNK_DURATION, min(value, self.MAX_CHUNK_DURATION)
            )

    @property
    def CHUNK_SIZE_BYTES(self) -> int:
        return int(
            self.CHUNK_DURATION
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def OVERLAP_SIZE_BYTES(self) -> int:
        return int(
            self.CHUNK_OVERLAP
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def BYTES_PER_SECOND(self) -> int:
        return self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE

    @property
    def MIN_CHUNK_BYTES(self) -> int:
        return int(self.MIN_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def MAX_CHUNK_BYTES(self) -> int:
        return int(self.MAX_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def INITIAL_BUFFER_BYTES(self) -> int:
        return int(self.INITIAL_BUFFER_SECONDS * self.BYTES_PER_SECOND)

    def get_timeout_microseconds(self, is_youtube: bool = False) -> int:
        return self.YOUTUBE_TIMEOUT if is_youtube else self.NORMAL_TIMEOUT

    def get_audio_filter(
        self, language: Optional[str] = None, profile: Optional[str] = None
    ) -> str:
        """Gibt einen Audiofilter basierend auf Sprache und Profil zurück."""
        # Basis: Standardfilter aus Konfiguration
        filter_str = self.AUDIO_FILTER

        # Wenn ein Profil angegeben ist und in FILTER_PROFILES existiert, verwende es
        if profile and profile in self.FILTER_PROFILES:
            filter_str = self.FILTER_PROFILES[profile]

        # Sprachspezifische Anpassungen (optional)
        if language and language in self.LANGUAGE_FILTERS:
            # Hier könnte man spezifische Filter für Sprachen hinterlegen
            # Aktuell überschreibt LANGUAGE_FILTERS nicht, sondern kann als Fallback dienen
            filter_str = self.LANGUAGE_FILTERS[language]

        return filter_str

    def get_youtube_headers(self, is_manifest: bool = False) -> Dict[str, str]:
        headers = self.YOUTUBE_HEADERS.copy()
        if is_manifest:
            headers.update(
                {"X-Client-Data": "CI22yQE=", "Content-Type": "application/x-mpegURL"}
            )
        return headers

    def get_platform_config(self, platform: Optional[str] = None) -> Dict[str, Any]:
        if not platform:
            platform = SYSTEM.lower()
        return self.PLATFORM_CONFIG.get(platform, self.PLATFORM_CONFIG["linux"])

    def __post_init__(self) -> None:
        self._actual_chunk_duration = float(self._base_chunk_duration)

    def calculate_optimal_chunk_duration(
        self, model_size: str = "medium", is_realtime: bool = False
    ) -> int:
        if is_realtime:
            return self.MIN_CHUNK_DURATION
        model_durations = {
            "tiny": 3,
            "tiny.en": 3,
            "base": 4,
            "base.en": 4,
            "small": 5,
            "small.en": 5,
            "medium": 5,
            "medium.en": 5,
            "large": 6,
            "large-v2": 6,
            "large-v3": 6,
            "large-v3-turbo": 5,   # neues Modell
        }
        return model_durations.get(model_size.lower(), self._base_chunk_duration)

    @classmethod
    def get_dynamic_max_memory(cls) -> int:
        """Ermittelt dynamisch die maximale Speichergrenze (75 % des verfügbaren RAM)."""
        try:
            import psutil
            return int(psutil.virtual_memory().total * 0.75)
        except ImportError:
            return cls.MAX_MEMORY_USAGE

    def validate_config(self) -> bool:
        try:
            return (
                self.SAMPLE_RATE in [8000, 16000, 22050, 44100, 48000]
                and self.CHANNELS in [1, 2]
                and self.MIN_CHUNK_DURATION
                <= self.CHUNK_DURATION
                <= self.MAX_CHUNK_DURATION
            )
        except Exception:
            return False

    def print_summary(self) -> None:
        logger.info("\n" + "=" * 60)
        logger.info("🎵 CONFIGURATION (optimized for precision)")
        logger.info("=" * 60)
        logger.info(f"📊 Audio: {self.SAMPLE_RATE}Hz, {self.CHANNELS}ch")
        logger.info(f"📦 Chunk: {self.CHUNK_DURATION}s ({self.CHUNK_SIZE_BYTES:,}B)")
        logger.info(f"⚡ Bytes/sec: {self.BYTES_PER_SECOND:,}")
        logger.info(f"🎛️ Filter: {self.AUDIO_FILTER}")
        logger.info(f"✅ Valid: {self.validate_config()}")
        logger.info("=" * 60)


class RealtimeConfig(Config):
    def __init__(self) -> None:
        super().__init__()
        self.CHUNK_DURATION = 5
        self.CHUNK_OVERLAP = 0.3
        self.STREAM_TIMEOUT = 5
        self.AUDIO_FILTER = self.FILTER_PROFILES["realtime"]


class HighAccuracyConfig(Config):
    def __init__(self) -> None:
        super().__init__()
        self.CHUNK_DURATION = 25
        self.CHUNK_OVERLAP = 0.8
        self.AUDIO_FILTER = (
            "aresample=16000,volume=1.8,highpass=f=80,"
            "lowpass=f=3800,dynaudnorm=p=0.3:s=3:g=20"
        )


class YouTubeOptimizedConfig(Config):
    def __init__(self) -> None:
        super().__init__()
        self.FFMPEG_THREADS = 1
        self.FFMPEG_BUFSIZE = "1024k"
        self.YOUTUBE_TIMEOUT = 5000000
        self.RECONNECT_DELAY = 1
        self.AUDIO_FILTER = (
            "aresample=16000,volume=2.2,highpass=f=120,"
            "lowpass=f=3200,compand=attacks=0:decays=0.3"
        )


def get_config(config_type: str = "default") -> Config:
    configs = {
        "default": Config,
        "realtime": RealtimeConfig,
        "high_accuracy": HighAccuracyConfig,
        "youtube": YouTubeOptimizedConfig,
    }
    config_class = configs.get(config_type, Config)
    config = config_class()
    config.validate_config()
    return config

# =============================================================================
# 11. HILFSKLASSEN (FastLazyLoader, PlatformStderrFilter, PlatformUtils, DummyQueue, SimplePerformanceTracker, OptimizedThreadPoolExecutor, TTLCache, LRUCache, CacheManager, DebugFilter, AppContext, log_exception, MemoryManager, Decorators)
# =============================================================================
class FastLazyLoader:
    _loaded_modules: Dict[str, Any] = {}
    _module_locks: Dict[str, threading.Lock] = {}
    _global_lock = threading.Lock()
    _availability_cache: Dict[str, Tuple[bool, float]] = {}
    _availability_cache_ttl: float = 60.0
    _metrics_enabled: bool = False
    _metrics: Dict[str, Any] = {
        "load_attempts": 0,
        "load_success": 0,
        "load_failures": 0,
        "cache_hits": 0,
        "availability_checks": 0,
    }
    _metrics_lock = threading.Lock()
    _cache_lock = threading.RLock()

    @classmethod
    def configure(cls, *, availability_cache_ttl: Optional[float] = None, enable_metrics: bool = False) -> None:
        if availability_cache_ttl is not None:
            cls._availability_cache_ttl = availability_cache_ttl
        cls._metrics_enabled = enable_metrics

    @classmethod
    def _get_lock(cls, module_name: str) -> threading.Lock:
        with cls._global_lock:
            if module_name not in cls._module_locks:
                cls._module_locks[module_name] = threading.Lock()
            return cls._module_locks[module_name]

    @classmethod
    def load(cls, module_name: str, import_paths: Union[str, List[str], None] = None) -> Any:
        if module_name in cls._loaded_modules:
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["cache_hits"] += 1
            return cls._loaded_modules[module_name]

        lock = cls._get_lock(module_name)
        with lock:
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                return cls._loaded_modules[module_name]

            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_attempts"] += 1

            if import_paths is None:
                paths = [module_name]
            elif isinstance(import_paths, str):
                paths = [import_paths]
            else:
                paths = import_paths

            special_handlers = {
                "torch": cls._load_torch,
                "faster_whisper": cls._load_faster_whisper,
                "numpy": cls._load_numpy,
                "deep_translator": cls._load_deep_translator,
                "scipy.signal": cls._load_scipy_signal,
            }

            if module_name in special_handlers:
                try:
                    module = special_handlers[module_name]()
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    return module
                except ImportError as e:
                    logger.warning(f"⚠️ Special handler for {module_name} failed: {e}")

            last_error = None
            for path in paths:
                try:
                    module = importlib.import_module(path)
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    return module
                except ImportError as e:
                    last_error = e
                    continue

            logger.warning(f"⚠️ Module {module_name} not available (tried paths: {paths}): {last_error}")
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_failures"] += 1

            class MockModule:
                _is_mock = True
                def __init__(self, name: str):
                    self.__name__ = name
                def __getattr__(self, name: str) -> Any:
                    def mock_method(*args: Any, **kwargs: Any) -> Any:
                        raise ImportError(f"Module {self.__name__} not available")
                    return mock_method
            mock = MockModule(module_name)
            cls._loaded_modules[module_name] = mock
            return mock

    @classmethod
    def _load_torch(cls):
        import torch
        try:
            import torch._logging
            torch._logging.set_logs(all=logging.ERROR)
        except Exception:
            pass
        return torch

    @classmethod
    def _load_faster_whisper(cls):
        from faster_whisper import WhisperModel
        return WhisperModel

    @classmethod
    def _load_numpy(cls):
        import numpy as np
        return np

    @classmethod
    def _load_deep_translator(cls):
        from deep_translator import GoogleTranslator
        return GoogleTranslator

    @classmethod
    def _load_scipy_signal(cls):
        import scipy.signal
        return scipy.signal

    @classmethod
    def is_available(cls, module_name: str, use_cache: bool = True) -> bool:
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics["availability_checks"] += 1

        if module_name in cls._loaded_modules:
            mod = cls._loaded_modules[module_name]
            return not getattr(mod, "_is_mock", False)

        if use_cache:
            now = time.time()
            with cls._cache_lock:
                cached = cls._availability_cache.get(module_name)
                if cached and (now - cached[1] < cls._availability_cache_ttl):
                    return cached[0]

        spec = importlib.util.find_spec(module_name)
        available = spec is not None

        if use_cache:
            with cls._cache_lock:
                cls._availability_cache[module_name] = (available, time.time())

        return available

    @classmethod
    def clear_cache(cls) -> None:
        with cls._global_lock:
            cls._loaded_modules.clear()
            cls._module_locks.clear()
            cls._availability_cache.clear()
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics = {
                        "load_attempts": 0,
                        "load_success": 0,
                        "load_failures": 0,
                        "cache_hits": 0,
                        "availability_checks": 0,
                    }

    @classmethod
    def get_metrics(cls) -> Dict[str, Any]:
        if not cls._metrics_enabled:
            return {}
        with cls._metrics_lock:
            return cls._metrics.copy()


class GPUStats:
    """
    Singleton‑artige Hilfsklasse für einmalige Initialisierung von pynvml.
    Stellt den GPU‑Handle und grundlegende Funktionen bereit.
    """
    _initialized = False
    _nvml_handle = None
    _nvml_available = False
    _lock = threading.Lock()

    @classmethod
    def _ensure_initialized(cls):
        """Initialisiert pynvml genau einmal."""
        if cls._initialized:
            return
        with cls._lock:
            if cls._initialized:
                return
            try:
                import pynvml
                pynvml.nvmlInit()
                cls._nvml_handle = pynvml.nvmlDeviceGetHandleByIndex(0)
                cls._nvml_available = True
            except (ImportError, pynvml.NVMLError) as e:
                logger.debug(f"pynvml nicht verfügbar: {e}")
                cls._nvml_available = False
            finally:
                cls._initialized = True

    @classmethod
    def is_available(cls) -> bool:
        """Gibt zurück, ob pynvml erfolgreich initialisiert wurde."""
        cls._ensure_initialized()
        return cls._nvml_available

    @classmethod
    def get_temperature(cls) -> Optional[int]:
        """Aktuelle GPU‑Temperatur in °C oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml
            return pynvml.nvmlDeviceGetTemperature(cls._nvml_handle,
                                                    pynvml.NVML_TEMPERATURE_GPU)
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_utilization(cls) -> Optional[int]:
        """GPU‑Auslastung in Prozent oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml
            return pynvml.nvmlDeviceGetUtilizationRates(cls._nvml_handle).gpu
        except pynvml.NVMLError:
            return None


class PlatformStderrFilter:
    def __init__(self, original_stderr: Any) -> None:
        self.original_stderr = original_stderr
        self.filter_patterns = [
            "mpp_soc:",
            "mpp_platform:",
            "can not found match soc name",
            "/proc/device-tree/compatible",
            "rockchip",
            "ffmpeg",
            "TORCH_NCCL",
        ]
        if IS_WINDOWS:
            self.filter_patterns.extend(
                [
                    "Failed to set direct console mode",
                    "Console code page",
                    "chcp",
                    "win32api",
                ]
            )

    def write(self, text: str) -> None:
        if text and any(p in text for p in self.filter_patterns):
            return
        self.original_stderr.write(text)

    def flush(self) -> None:
        self.original_stderr.flush()


if DEBUG_LEVEL < 3:
    sys.stderr = PlatformStderrFilter(sys.stderr)
else:
    sys.stderr = sys.__stderr__


class PlatformUtils:
    """
    Plattformunabhängige Hilfsfunktionen für Dragon Whisperer.

    Kümmert sich um Umgebungsvariablen, Konsolen‑Setup, Prozessverwaltung,
    URL‑ und Pfad‑Validierung sowie Terminal‑Einstellungen.
    Alle öffentlichen Methoden sind thread‑sicher.
    """

    # =========================================================================
    #  Klassenattribute
    # =========================================================================
    _environment_setup_done = False
    _environment_setup_lock = threading.RLock()
    _dependencies_checked = False
    _dependencies_lock = threading.RLock()
    _ffmpeg_path: Optional[str] = None
    _ffmpeg_path_lock = threading.RLock()
    _terminal_settings_saved = False
    _original_stty_settings: Optional[str] = None
    _terminal_lock = threading.Lock()

    # Lazy‑Initialisierung für erlaubte Verzeichnisse
    _allowed_dirs: Optional[List[Path]] = None
    _allowed_dirs_lock = threading.RLock()

    # Für Tests überschreibbare Pfade
    _test_home: Optional[Path] = None
    _test_cwd: Optional[Path] = None

    # Debug‑Komponente
    _DEBUG_COMPONENT = "platform"

    # -------------------------------------------------------------------------
    #  Öffentliche Methoden
    # -------------------------------------------------------------------------
    @classmethod
    def set_allowed_dirs(cls, dirs: List[str]) -> None:
        """
        Setzt die Liste der erlaubten Basisverzeichnisse (nach dem Laden der Config aufrufen).
        """
        logger = logging.getLogger("dragon")
        logger.debug(f"Set allowed dirs: {dirs}", extra={"component": cls._DEBUG_COMPONENT})

        with cls._allowed_dirs_lock:
            resolved = []
            for d in dirs:
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                    if p.exists():
                        resolved.append(p)
                        logger.debug(f"  → Resolved: {p}", extra={"component": cls._DEBUG_COMPONENT})
                    else:
                        logger.debug(f"  → Skipped (does not exist): {d}", extra={"component": cls._DEBUG_COMPONENT})
                except Exception as e:
                    logger.debug(f"  → Skipped (invalid path): {d} – {e}", extra={"component": cls._DEBUG_COMPONENT})
            cls._allowed_dirs = resolved
            logger.debug(f"Final allowed dirs: {[str(p) for p in resolved]}", extra={"component": cls._DEBUG_COMPONENT})

    @classmethod
    def get_platform_config_dir(cls) -> Path:
        """Gibt das plattformspezifische Konfigurationsverzeichnis zurück (ohne es zu erstellen)."""
        if IS_WINDOWS:
            appdata = os.environ.get("APPDATA")
            if not appdata:
                appdata = str(Path.home() / "AppData" / "Roaming")
                logging.getLogger("dragon").debug(
                    "APPDATA not set, fallback to: %s", appdata,
                    extra={"component": cls._DEBUG_COMPONENT}
                )
            config_dir = Path(appdata) / "DragonWhisperer"
        elif IS_MACOS:
            config_dir = Path.home() / "Library" / "Application Support" / "DragonWhisperer"
        else:
            config_dir = Path.home() / ".config" / "dragonwhisperer"
        logging.getLogger("dragon").debug(
            f"Config directory: {config_dir}", extra={"component": cls._DEBUG_COMPONENT}
        )
        return config_dir

    @classmethod
    def ensure_platform_config_dir(cls) -> Path:
        """Stellt sicher, dass das Konfigurationsverzeichnis existiert, und gibt es zurück."""
        config_dir = cls.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
        logging.getLogger("dragon").debug(
            f"Ensured config directory exists: {config_dir}", extra={"component": cls._DEBUG_COMPONENT}
        )
        return config_dir

    @classmethod
    def kill_process_tree(cls, pid: int) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse.
        Verwendet psutil, falls vorhanden, ansonsten plattformspezifische Befehle.
        """
        logger = logging.getLogger("dragon")
        logger.debug(f"Killing process tree for PID {pid}", extra={"component": cls._DEBUG_COMPONENT})

        try:
            import psutil
            parent = psutil.Process(pid)
            children = parent.children(recursive=True)
            logger.debug(f"  Found {len(children)} child processes", extra={"component": cls._DEBUG_COMPONENT})
            for child in children:
                try:
                    child.terminate()
                    logger.debug(f"    Terminated child {child.pid}", extra={"component": cls._DEBUG_COMPONENT})
                except psutil.NoSuchProcess:
                    pass
            gone, alive = psutil.wait_procs(children, timeout=2.0)
            for child in alive:
                try:
                    child.kill()
                    logger.debug(f"    Killed child {child.pid}", extra={"component": cls._DEBUG_COMPONENT})
                except psutil.NoSuchProcess:
                    pass
            parent.terminate()
            parent.wait(timeout=2.0)
            logger.debug(f"  Terminated parent {pid}", extra={"component": cls._DEBUG_COMPONENT})
            return True
        except ImportError:
            logger.debug("  psutil not available, using fallback", extra={"component": cls._DEBUG_COMPONENT})
        except Exception as e:
            logger.debug(f"  psutil error: {e}", extra={"component": cls._DEBUG_COMPONENT})

        try:
            if IS_WINDOWS:
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=5,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                logger.debug(f"  Used taskkill for PID {pid}", extra={"component": cls._DEBUG_COMPONENT})
                return True
            else:
                try:
                    os.killpg(os.getpgid(pid), py_signal.SIGKILL)
                    logger.debug(f"  Used killpg for PID {pid}", extra={"component": cls._DEBUG_COMPONENT})
                except (ProcessLookupError, PermissionError):
                    subprocess.run(
                        ["pkill", "-9", "-P", str(pid)],
                        capture_output=True,
                        timeout=5,
                        check=False,
                    )
                    logger.debug(f"  Used pkill for PID {pid}", extra={"component": cls._DEBUG_COMPONENT})
                return True
        except subprocess.TimeoutExpired:
            logger.debug(f"  Timeout killing process tree {pid}", extra={"component": cls._DEBUG_COMPONENT})
        except (OSError, subprocess.CalledProcessError) as e:
            logger.debug(f"  Error killing process tree {pid}: {e}", extra={"component": cls._DEBUG_COMPONENT})
        except Exception as e:
            logger.debug(f"  Unexpected error killing process tree {pid}: {e}", extra={"component": cls._DEBUG_COMPONENT})
        return False

    @classmethod
    def check_platform_dependencies(cls) -> bool:
        """Prüft, ob alle kritischen Abhängigkeiten vorhanden sind. Wirft RuntimeError bei Fehlern."""
        with cls._dependencies_lock:
            if cls._dependencies_checked:
                logging.getLogger("dragon").debug(
                    "Dependencies already checked, skipping", extra={"component": cls._DEBUG_COMPONENT}
                )
                return True

            missing_critical: List[str] = []
            missing_optional: List[str] = []
            issues: List[str] = []

            logger = logging.getLogger("dragon")
            logger.info("🔍 Checking platform dependencies...")
            logger.debug("Starting dependency check", extra={"component": cls._DEBUG_COMPONENT})

            ffmpeg_found = cls.get_ffmpeg_path() is not None
            if not ffmpeg_found:
                missing_critical.append("ffmpeg")
                issues.append("FFmpeg not found in PATH or standard locations")
                logger.debug("  ✗ ffmpeg missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ ffmpeg found", extra={"component": cls._DEBUG_COMPONENT})

            ytdlp_found = shutil.which("yt-dlp") is not None
            if not ytdlp_found:
                missing_critical.append("yt-dlp")
                issues.append("yt-dlp not found in PATH")
                logger.debug("  ✗ yt-dlp missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ yt-dlp found", extra={"component": cls._DEBUG_COMPONENT})

            if not GUI_AVAILABLE:
                missing_critical.append("tkinter")
                issues.append("Tkinter not available – required for GUI")
                logger.debug("  ✗ tkinter missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ tkinter available", extra={"component": cls._DEBUG_COMPONENT})

            if not NUMPY_AVAILABLE:
                missing_critical.append("numpy")
                issues.append("numpy not available – required for audio processing and Whisper")
                logger.debug("  ✗ numpy missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ numpy available", extra={"component": cls._DEBUG_COMPONENT})

            if not WHISPER_AVAILABLE:
                missing_optional.append("whisper (faster-whisper/openai-whisper)")
                logger.warning("⚠️ Kein Whisper-Backend verfügbar. Starte im Demo-Modus.")
                logger.debug("  ⚠ whisper backend missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ whisper backend available", extra={"component": cls._DEBUG_COMPONENT})

            if not TRANSLATOR_AVAILABLE:
                missing_optional.append("deep-translator")
                issues.append("deep-translator not available (translation will be limited)")
                logger.debug("  ✗ deep-translator missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ deep-translator available", extra={"component": cls._DEBUG_COMPONENT})

            if not TORCH_AVAILABLE:
                missing_optional.append("torch")
                issues.append("PyTorch not available (optional for GPU acceleration)")
                logger.debug("  ✗ torch missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ torch available", extra={"component": cls._DEBUG_COMPONENT})

            if not FastLazyLoader.is_available("psutil"):
                missing_optional.append("psutil")
                issues.append("psutil not available (system monitoring limited)")
                logger.debug("  ✗ psutil missing", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("  ✓ psutil available", extra={"component": cls._DEBUG_COMPONENT})

            if missing_critical:
                error_msg = f"❌ Fehlende kritische Abhängigkeiten: {', '.join(missing_critical)}\n\n"
                error_msg += "\n".join(issues) + "\n"

                if "ffmpeg" in missing_critical:
                    error_msg += "\nFFmpeg Installation:\n"
                    if IS_WINDOWS:
                        error_msg += "  • Download from: https://ffmpeg.org/download.html\n"
                    elif IS_MACOS:
                        error_msg += "  • brew install ffmpeg\n"
                    else:
                        error_msg += "  • sudo apt install ffmpeg\n"
                if "yt-dlp" in missing_critical:
                    error_msg += "\nyt-dlp Installation:\n"
                    error_msg += "  • pip install yt-dlp\n"
                if "tkinter" in missing_critical:
                    error_msg += "\nTkinter Installation:\n"
                    error_msg += "  • Usually included with Python. On Linux: sudo apt-get install python3-tk\n"
                if "numpy" in missing_critical:
                    error_msg += "\nnumpy Installation:\n"
                    error_msg += "  • pip install numpy\n"

                error_msg += "\n💡 Nach der Installation starten Sie Dragon Whisperer neu."
                cls._dependencies_checked = False
                raise RuntimeError(error_msg)

            if missing_optional:
                logger.warning(f"⚠️ Optionale Pakete fehlen: {', '.join(missing_optional)}")
                logger.debug(f"Missing optional packages: {missing_optional}", extra={"component": cls._DEBUG_COMPONENT})
            if issues:
                for issue in issues:
                    logger.warning(f"⚠️ {issue}")
                    logger.debug(f"  Issue: {issue}", extra={"component": cls._DEBUG_COMPONENT})

            logger.info("✅ Alle kritischen Abhängigkeiten gefunden")
            cls._dependencies_checked = True
            logger.debug("Dependency check completed", extra={"component": cls._DEBUG_COMPONENT})
            return True

    @classmethod
    def setup_platform_environment(cls) -> None:
        """Richtet plattformspezifische Umgebungsvariablen und Konsolen ein."""
        with cls._environment_setup_lock:
            if cls._environment_setup_done:
                logging.getLogger("dragon").debug(
                    "Environment already set up", extra={"component": cls._DEBUG_COMPONENT}
                )
                return

            logger = logging.getLogger("dragon")
            logger.info("🔧 Setting up platform environment...")
            logger.debug("Starting environment setup", extra={"component": cls._DEBUG_COMPONENT})

            cls._save_terminal_settings()
            atexit.register(cls._restore_terminal_settings)

            if IS_WINDOWS:
                cls._setup_windows_console()
                logger.debug("Windows console setup completed", extra={"component": cls._DEBUG_COMPONENT})
            elif IS_MACOS:
                cls._setup_macos_temp_dir()
                logger.debug("macOS temp dir setup completed", extra={"component": cls._DEBUG_COMPONENT})
            else:
                logger.debug("Linux: no extra setup needed", extra={"component": cls._DEBUG_COMPONENT})

            cls._environment_setup_done = True
            logger.info("✅ Platform environment setup complete")
            logger.debug("Environment setup finished", extra={"component": cls._DEBUG_COMPONENT})

    @classmethod
    def get_ffmpeg_path(cls) -> Optional[str]:
        """Ermittelt den Pfad zur FFmpeg‑Executable (cached, thread‑sicher)."""
        with cls._ffmpeg_path_lock:
            if cls._ffmpeg_path is not None:
                logging.getLogger("dragon").debug(
                    f"FFmpeg path from cache: {cls._ffmpeg_path}",
                    extra={"component": cls._DEBUG_COMPONENT}
                )
                return cls._ffmpeg_path

            env_path = os.environ.get('FFMPEG_PATH')
            if env_path and os.path.exists(env_path):
                cls._ffmpeg_path = env_path
                logging.getLogger("dragon").debug(
                    f"FFmpeg from FFMPEG_PATH env: {env_path}",
                    extra={"component": cls._DEBUG_COMPONENT}
                )
                return cls._ffmpeg_path

            ffmpeg_path = shutil.which("ffmpeg")
            if ffmpeg_path:
                cls._ffmpeg_path = ffmpeg_path
                logging.getLogger("dragon").debug(
                    f"FFmpeg found in PATH: {ffmpeg_path}",
                    extra={"component": cls._DEBUG_COMPONENT}
                )
                return cls._ffmpeg_path

            # Plattformspezifische Fallback‑Pfade
            if IS_WINDOWS:
                paths = [
                    "C:\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files (x86)\\ffmpeg\\bin\\ffmpeg.exe",
                ]
            elif IS_MACOS:
                paths = [
                    "/usr/local/bin/ffmpeg",
                    "/opt/homebrew/bin/ffmpeg",
                    "/usr/bin/ffmpeg",
                ]
            else:
                paths = [
                    "/usr/bin/ffmpeg",
                    "/usr/local/bin/ffmpeg",
                ]

            for path in paths:
                if os.path.exists(path):
                    cls._ffmpeg_path = path
                    logging.getLogger("dragon").debug(
                        f"FFmpeg found at fallback path: {path}",
                        extra={"component": cls._DEBUG_COMPONENT}
                    )
                    return cls._ffmpeg_path

            logging.getLogger("dragon").debug(
                "FFmpeg not found anywhere", extra={"component": cls._DEBUG_COMPONENT}
            )
            cls._ffmpeg_path = None
            return None

    @classmethod
    def get_platform_info(cls) -> Dict[str, Any]:
        """Liefert ein Dictionary mit detaillierten Plattforminformationen."""
        info: Dict[str, Any] = {
            "system": SYSTEM,
            "is_windows": IS_WINDOWS,
            "is_macos": IS_MACOS,
            "is_linux": IS_LINUX,
            "is_arm": IS_ARM,
            "is_x86": IS_X86,
            "python_version": sys.version,
            "python_executable": sys.executable,
            "current_directory": os.getcwd(),
            "environment_setup": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
        }

        try:
            import psutil
            info["cpu_count"] = psutil.cpu_count()
            info["memory_total_gb"] = psutil.virtual_memory().total / (1024**3)
        except ImportError:
            info["cpu_count"] = None
            info["memory_total_gb"] = None
        except Exception as e:
            logger = logging.getLogger("dragon")
            logger.error(f"Fehler beim Abrufen der Systeminformationen: {e}")
            info["cpu_count"] = None
            info["memory_total_gb"] = None

        return info

    @classmethod
    def print_platform_info(cls) -> None:
        """Gibt die Plattforminformationen im Log aus."""
        info = cls.get_platform_info()
        logger = logging.getLogger("dragon")
        logger.info("\n" + "=" * 60)
        logger.info("🐉 PLATFORM INFORMATION")
        logger.info("=" * 60)
        for key, value in info.items():
            if key not in ["environment_setup", "dependencies_checked"]:
                logger.info(f"{key:25} {value}")
        logger.info("-" * 60)
        logger.info(f"{'Environment Setup':25} {'✅' if info['environment_setup'] else '❌'}")
        logger.info(f"{'Dependencies Checked':25} {'✅' if info['dependencies_checked'] else '❌'}")
        logger.info("=" * 60)

    @classmethod
    def get_debug_info(cls) -> Dict[str, Any]:
        """
        Liefert detaillierte Debug‑Informationen über den internen Zustand.
        Nützlich für die Fehlersuche mit --debug=3.
        """
        with cls._allowed_dirs_lock:
            allowed_dirs = [str(p) for p in cls._allowed_dirs] if cls._allowed_dirs else []
        return {
            "allowed_dirs": allowed_dirs,
            "ffmpeg_path": cls._ffmpeg_path,
            "terminal_settings_saved": cls._terminal_settings_saved,
            "original_stty_settings": cls._original_stty_settings,
            "environment_setup_done": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "test_home_override": str(cls._test_home) if cls._test_home else None,
            "test_cwd_override": str(cls._test_cwd) if cls._test_cwd else None,
        }

    @classmethod
    def set_test_home(cls, path: Optional[Path]) -> None:
        """
        Überschreibt das Home‑Verzeichnis für Tests.
        Nur zu Testzwecken verwenden.
        """
        cls._test_home = path
        logging.getLogger("dragon").debug(
            f"Test home set to: {path}", extra={"component": cls._DEBUG_COMPONENT}
        )

    @classmethod
    def set_test_cwd(cls, path: Optional[Path]) -> None:
        """
        Überschreibt das aktuelle Arbeitsverzeichnis für Tests.
        Nur zu Testzwecken verwenden.
        """
        cls._test_cwd = path
        logging.getLogger("dragon").debug(
            f"Test cwd set to: {path}", extra={"component": cls._DEBUG_COMPONENT}
        )

    @classmethod
    def sanitize_url(cls, url: str) -> str:
        """Entfernt überflüssige Whitespaces und bereinigt die URL."""
        return url.strip() if url else ""

    @classmethod
    def validate_file_path(cls, file_url: str, allowed_dirs: Optional[List[str]] = None) -> Tuple[bool, str]:
        """
        Validiert eine file://‑URL.
        Gibt (True, absoluter Pfad) oder (False, Fehlermeldung) zurück.
        Wenn allowed_dirs übergeben wird, werden diese zusätzlich zu den Standard‑Verzeichnissen erlaubt.
        """
        logger = logging.getLogger("dragon")
        logger.debug(f"Validating file URL: {file_url}", extra={"component": cls._DEBUG_COMPONENT})

        if not file_url.startswith("file://"):
            logger.debug("Not a file:// URL", extra={"component": cls._DEBUG_COMPONENT})
            return False, "Keine file://-URL"

        try:
            if IS_WINDOWS and file_url.startswith("file:///"):
                path_part = file_url[8:]
                path_part = urllib.request.url2pathname(path_part)
            else:
                path_part = file_url[len("file://"):]

            if not IS_WINDOWS or not path_part.startswith("\\\\"):
                path_part = os.path.normpath(path_part)

        except Exception as e:
            logger.debug(f"Failed to extract path: {e}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"Pfad kann nicht extrahiert werden: {e}"

        try:
            real_path = Path(path_part).resolve()
        except Exception as e:
            logger.debug(f"Failed to resolve path: {e}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"Pfad kann nicht normalisiert werden: {e}"

        if not real_path.exists():
            logger.debug(f"File does not exist: {real_path}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"Datei existiert nicht: {real_path}"
        if not real_path.is_file():
            logger.debug(f"Not a file: {real_path}", extra={"component": cls._DEBUG_COMPONENT})
            return False, "Keine gültige Datei (möglicherweise ein Verzeichnis)"

        # Erlaubte Verzeichnisse ermitteln
        allowed_bases = cls._get_allowed_dirs()
        if allowed_dirs:
            for d in allowed_dirs:
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                    if p.exists():
                        allowed_bases.append(p)
                except Exception as e:
                    logger.debug(f"Invalid allowed dir: {d} – {e}", extra={"component": cls._DEBUG_COMPONENT})
        allowed_bases.append(Path(tempfile.gettempdir()).resolve())

        if not allowed_bases:
            logger.debug("No allowed directories defined", extra={"component": cls._DEBUG_COMPONENT})
            return False, "Keine erlaubten Verzeichnisse definiert"

        for base in allowed_bases:
            try:
                real_path.relative_to(base)
                logger.debug(f"File allowed under base: {base}", extra={"component": cls._DEBUG_COMPONENT})
                return True, str(real_path)
            except ValueError:
                continue

        logger.debug(
            f"File outside allowed directories: {real_path} – Allowed: {allowed_bases}",
            extra={"component": cls._DEBUG_COMPONENT}
        )
        return False, "Datei außerhalb der erlaubten Verzeichnisse (nur Home, aktuelles Verzeichnis und /tmp)"

    @classmethod
    def validate_url(cls, url: str) -> Tuple[bool, str]:
        """Validiert eine beliebige URL (http, https, file, dvb, ...)."""
        if not url:
            return False, "URL is empty"

        url = cls.sanitize_url(url)
        logger = logging.getLogger("dragon")
        logger.debug(f"Validating URL: {url}", extra={"component": cls._DEBUG_COMPONENT})

        if url.startswith(("dvb://", "dvb-s://")):
            return cls._validate_dvb_url(url)
        if url.startswith("file://"):
            return cls.validate_file_path(url)

        if not url.startswith(("http://", "https://")):
            logger.debug(f"Unsupported scheme: {url[:50]}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"Nicht unterstütztes URL-Schema: {url[:50]}"

        try:
            parsed = urllib.parse.urlparse(url)
            if not parsed.netloc:
                logger.debug("No network location in URL", extra={"component": cls._DEBUG_COMPONENT})
                return False, "Keine Netzwerkadresse in URL"

            allowed_chars = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
            components = parsed.path + parsed.query + parsed.fragment + parsed.params
            if not re.match(f"^[{allowed_chars}]*$", components):
                logger.debug(f"Invalid characters: {components[:50]}", extra={"component": cls._DEBUG_COMPONENT})
                return False, f"URL enthält nicht erlaubte Zeichen: {components[:50]}"

            logger.debug("URL valid", extra={"component": cls._DEBUG_COMPONENT})
            return True, "ok"
        except Exception as e:
            logger.debug(f"URL parsing failed: {e}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"URL-Parsing fehlgeschlagen: {e}"

    # =========================================================================
    #  NEUE ZENTRALE PROZESS-TERMINIERUNG
    # =========================================================================
    @staticmethod
    def terminate_process(
        proc: subprocess.Popen,
        *,
        child_terminate_timeout: float = 2.0,
        child_kill_wait: float = 1.0,
        parent_terminate_timeout: float = 2.0,
        parent_kill_wait: float = 1.0,
        fallback_terminate_timeout: float = 2.0,
        fallback_kill_wait: float = 1.0,
        stats_callback: Optional[Callable[[str], None]] = None,
    ) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse robust.
        Gibt True zurück, wenn der Prozess erfolgreich beendet wurde.

        Args:
            proc: Der zu beendende subprocess.Popen
            child_terminate_timeout: Timeout für Kindprozesse (terminate)
            child_kill_wait: Wartezeit nach kill für Kindprozesse
            parent_terminate_timeout: Timeout für Elternprozess (terminate)
            parent_kill_wait: Wartezeit nach kill für Elternprozess
            fallback_terminate_timeout: Timeout für Fallback (ohne psutil)
            fallback_kill_wait: Wartezeit nach kill im Fallback
            stats_callback: Optionaler Callback, der den Erfolgsmodus erhält:
                            "psutil", "psutil_kill", "terminate", "kill", "failed", "exception"
        """
        if proc.poll() is not None:
            return True

        pid = proc.pid
        logger = logging.getLogger("dragon")
        logger.debug(f"🛑 Beende Prozess {pid}...")

        # 1. Versuch: psutil (falls verfügbar)
        try:
            import psutil
            try:
                parent = psutil.Process(pid)
                children = parent.children(recursive=True)

                # Kindprozesse terminieren
                for child in children:
                    try:
                        child.terminate()
                    except psutil.NoSuchProcess:
                        pass

                # Auf Kindprozesse warten
                gone, alive = psutil.wait_procs(children, timeout=child_terminate_timeout)
                for p in alive:
                    try:
                        p.kill()
                    except psutil.NoSuchProcess:
                        pass

                # Elternprozess terminieren
                parent.terminate()
                try:
                    parent.wait(timeout=parent_terminate_timeout)
                    logger.debug(f"✅ Prozess {pid} mit psutil beendet")
                    if stats_callback:
                        stats_callback("psutil")
                    return True
                except psutil.TimeoutExpired:
                    # Elternprozess killen
                    parent.kill()
                    try:
                        parent.wait(timeout=parent_kill_wait)
                        logger.debug(f"✅ Prozess {pid} nach kill beendet")
                        if stats_callback:
                            stats_callback("psutil_kill")
                        return True
                    except psutil.TimeoutExpired:
                        logger.warning(f"⚠️ Prozess {pid} auch nach kill nicht beendet")
                        if stats_callback:
                            stats_callback("failed")
                        return False
            except (psutil.NoSuchProcess, psutil.AccessDenied, AttributeError) as e:
                logger.debug(f"psutil-Cleanup für {pid} fehlgeschlagen: {e}")
        except ImportError:
            logger.debug("psutil nicht verfügbar – verwende Fallback")

        # 2. Fallback ohne psutil
        try:
            proc.terminate()
            try:
                proc.wait(timeout=fallback_terminate_timeout)
                logger.debug(f"✅ Prozess {pid} mit terminate beendet")
                if stats_callback:
                    stats_callback("terminate")
                return True
            except subprocess.TimeoutExpired:
                logger.debug(f"⏰ Prozess {pid} reagiert nicht auf terminate, versuche kill")
                proc.kill()
                try:
                    proc.wait(timeout=fallback_kill_wait)
                    logger.debug(f"✅ Prozess {pid} mit kill beendet")
                    if stats_callback:
                        stats_callback("kill")
                    return True
                except subprocess.TimeoutExpired:
                    # Letzter Versuch: kurz warten und dann poll
                    time.sleep(0.5)
                    if proc.poll() is None:
                        logger.warning(f"⚠️ Prozess {pid} konnte nicht beendet werden")
                        if stats_callback:
                            stats_callback("failed")
                        return False
                    else:
                        logger.debug(f"✅ Prozess {pid} nach kill erfolgreich beendet")
                        if stats_callback:
                            stats_callback("kill")
                        return True
        except Exception as e:
            logger.warning(f"⚠️ Fehler beim Beenden von Prozess {pid}: {e}")
            if stats_callback:
                stats_callback("exception")
            return False

    # =========================================================================
    #  Private Hilfsmethoden
    # =========================================================================
    @classmethod
    def _get_allowed_dirs(cls) -> List[Path]:
        """Lazy‑Initialisierung der erlaubten Verzeichnisse (thread‑sicher)."""
        with cls._allowed_dirs_lock:
            if cls._allowed_dirs is None:
                # Standard‑Verzeichnisse
                cls._allowed_dirs = [
                    cls._get_home().resolve(),
                    cls._get_cwd().resolve(),
                    Path(tempfile.gettempdir()).resolve(),
                ]
                cache_dir = cls._get_home() / ".cache" / "dragonwhisperer"
                if cache_dir.exists():
                    cls._allowed_dirs.append(cache_dir.resolve())

                # Benutzerdefinierte Verzeichnisse aus den erweiterten Einstellungen laden
                try:
                    if 'AdvancedSettings' in globals():
                        settings = globals()['AdvancedSettings'].load_from_file()
                        if hasattr(settings, 'allowed_dirs') and settings.allowed_dirs:
                            for d in settings.allowed_dirs:
                                if d:
                                    try:
                                        p = Path(d).resolve()
                                        if p.exists():
                                            cls._allowed_dirs.append(p)
                                    except Exception:
                                        pass
                    else:
                        # Klasse noch nicht definiert – späterer Zugriff erfolgt automatisch,
                        # da die Methode erst nach der Definition aufgerufen wird.
                        pass
                except Exception as e:
                    logger = logging.getLogger("dragon")
                    logger.debug(f"Fehler beim Laden benutzerdefinierter Verzeichnisse: {e}",
                                 extra={"component": cls._DEBUG_COMPONENT})

            return cls._allowed_dirs

    @classmethod
    def _get_home(cls) -> Path:
        """Gibt das Home‑Verzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_home:
            return cls._test_home
        return Path.home()

    @classmethod
    def _get_cwd(cls) -> Path:
        """Gibt das aktuelle Arbeitsverzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_cwd:
            return cls._test_cwd
        return Path.cwd()

    @classmethod
    def _validate_dvb_url(cls, url: str) -> Tuple[bool, str]:
        """Validiert eine DVB‑URL (dvb:// oder dvb-s://)."""
        logger = logging.getLogger("dragon")
        params_part = url[8:] if url.startswith("dvb-s://") else url[6:]
        allowed = r"a-zA-Z0-9=&\-_.+"
        if not re.match(f"^[{allowed}]*$", params_part):
            logger.debug(f"Invalid DVB parameters: {params_part[:50]}", extra={"component": cls._DEBUG_COMPONENT})
            return False, f"DVB-Parameter enthalten ungültige Zeichen: {params_part[:50]}"

        if 'frequency=' not in params_part:
            logger.debug("Missing 'frequency' in DVB URL", extra={"component": cls._DEBUG_COMPONENT})
            return False, "DVB-URL muss 'frequency=' enthalten"

        logger.debug("DVB URL valid", extra={"component": cls._DEBUG_COMPONENT})
        return True, "ok"

    @classmethod
    def _setup_windows_console(cls):
        """Aktiviert UTF‑8 und virtuelle Terminal‑Sequenzen unter Windows."""
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            kernel32.SetConsoleOutputCP(65001)
            kernel32.SetConsoleCP(65001)
            os.system("chcp 65001 > nul 2>&1")
            os.system("color")

            handle = kernel32.GetStdHandle(-11)
            mode = ctypes.c_ulong()
            if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
                new_mode = mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING
                kernel32.SetConsoleMode(handle, new_mode)
                logging.getLogger("dragon").debug(
                    "Windows console: UTF-8 and VT processing enabled",
                    extra={"component": cls._DEBUG_COMPONENT}
                )
        except Exception as e:
            logger = logging.getLogger("dragon")
            logger.warning(f"⚠️ Windows console setup failed: {e}")

    @classmethod
    def _setup_macos_temp_dir(cls):
        """Erstellt ein temporäres Verzeichnis für Dragon Whisperer unter macOS."""
        temp_dir = Path(tempfile.gettempdir()) / "dragonwhisperer"
        try:
            temp_dir.mkdir(exist_ok=True)
            logging.getLogger("dragon").debug(
                f"macOS temp dir ensured: {temp_dir}",
                extra={"component": cls._DEBUG_COMPONENT}
            )
        except (OSError, PermissionError) as e:
            logger = logging.getLogger("dragon")
            logger.warning(f"⚠️ macOS temp dir creation failed: {e}")

    @classmethod
    def _save_terminal_settings(cls):
        """Speichert die aktuellen Terminal‑Einstellungen (Linux)."""
        if not IS_LINUX or cls._terminal_settings_saved:
            return
        with cls._terminal_lock:
            try:
                result = subprocess.run(
                    ["stty", "-g"], capture_output=True, text=True, check=False, timeout=2
                )
                if result.returncode == 0 and result.stdout:
                    cls._original_stty_settings = result.stdout.strip()
                    cls._terminal_settings_saved = True
                    logging.getLogger("dragon").debug(
                        "Terminal settings saved",
                        extra={"component": cls._DEBUG_COMPONENT}
                    )
            except (subprocess.TimeoutExpired, OSError):
                if DEBUG_LEVEL >= 2:
                    logger = logging.getLogger("dragon")
                    logger.debug("stty -g failed")

    @classmethod
    def _restore_terminal_settings(cls):
        """Stellt die ursprünglichen Terminal‑Einstellungen wieder her (Linux)."""
        if not IS_LINUX or cls._original_stty_settings is None:
            return
        with cls._terminal_lock:
            try:
                subprocess.run(["stty", cls._original_stty_settings], check=False, timeout=2)
                logging.getLogger("dragon").debug(
                    "Terminal settings restored",
                    extra={"component": cls._DEBUG_COMPONENT}
                )
            except Exception:
                pass


