class TTSManager:
    """
    Text-to-Speech Manager mit Piper (primär), pyttsx3 und espeak (Fallback).
    Unterstützt mehrere Audio-Player mit automatischem Fallback, Chunking langer Texte,
    Lautstärkeregelung und umfangreicher Fehlerdiagnose.

    Features:
        - Piper: hochwertige, offline Sprachausgabe (benötigt installierte Stimme)
        - pyttsx3: systemeigene Engine (Windows/macOS/Linux)
        - espeak: leichtgewichtige Alternative (Linux)
        - Automatischer Fallback auf nächstverfügbaren Audio-Player bei Fehlern
        - Aufteilung langer Texte in Sätze/Chunks zur Vermeidung von Buffer-Überläufen
        - Lautstärkeregelung (für unterstützte Player)
        - Detaillierte Debug-Ausgaben bei --debug=3
        - Thread-sichere, asynchrone Ausführung mit Abbruchmöglichkeit
    """

    # Priorität der Audio-Player (höherer Index = niedrigere Priorität)
    _PLAYER_PRIORITY = [
        ("aplay", ["aplay", "-r", "22050", "-f", "S16_LE", "-t", "raw"]),
        ("ffplay", ["ffplay", "-autoexit", "-nodisp", "-f", "s16le", "-ar", "22050", "-ac", "1", "-i", "pipe:0"]),
        ("paplay", ["paplay", "--format=s16le", "--rate=22050", "--channels=1"]),
        ("sox", ["play", "-t", "raw", "-r", "22050", "-e", "signed", "-b", "16", "-c", "1", "-"]),
    ]

    # Maximale Länge eines Chunks in Zeichen (verhindert Überlauf)
    MAX_CHUNK_LEN = 500

    def __init__(self, settings: "AdvancedSettings") -> None:
        """
        Initialisiert den TTS-Manager.

        Args:
            settings: Erweiterte Einstellungen (enthält TTS-Parameter).
        """
        self.settings = settings
        self._process: Optional[subprocess.Popen] = None          # Piper-Prozess
        self._speaking_thread: Optional[threading.Thread] = None  # Hauptthread für `speak`
        self._forward_thread: Optional[threading.Thread] = None   # Datenweiterleitung von Piper zu Audio-Player
        self._stop_requested = threading.Event()
        self._lock = threading.RLock()

        # TTS-Parameter aus den Einstellungen
        self._voice = getattr(settings, 'tts_voice', 'de_DE-thorsten-medium')
        self._length_scale = getattr(settings, 'tts_length_scale', 0.9)
        self._sentence_silence = getattr(settings, 'tts_sentence_silence', 0.1)
        self._volume = getattr(settings, 'tts_volume', 1.0)       # 0.0 - 1.0, wo unterstützt

        # Verfügbare Audio-Player ermitteln (wird bei Fehlern dynamisch aktualisiert)
        self._available_players = self._detect_audio_players()
        if not self._available_players:
            logger.warning("⚠️ Kein Audio-Player (ffplay, aplay, paplay, play) gefunden – TTS wird nicht funktionieren.")

        # Verfügbare TTS-Engines erkennen (für dynamischen Fallback)
        self._available_engines = self._detect_engines()

    # -------------------------------------------------------------------------
    #  Hilfsmethoden für Erkennung
    # -------------------------------------------------------------------------
    def _detect_audio_players(self) -> List[Tuple[str, List[str]]]:
        """Ermittelt verfügbare Audio-Player auf dem System."""
        players = []
        for name, cmd in self._PLAYER_PRIORITY:
            if shutil.which(cmd[0]):
                players.append((name, cmd))
                logger.debug(f"✅ Audio-Player gefunden: {name}")
        return players

    def _detect_engines(self) -> List[str]:
        """Ermittelt verfügbare TTS-Engines."""
        engines = []
        if shutil.which("piper") and self._available_players:
            engines.append("piper")
        if importlib.util.find_spec("pyttsx3") is not None:
            engines.append("pyttsx3")
        if shutil.which("espeak"):
            engines.append("espeak")
        return engines

    # -------------------------------------------------------------------------
    # Öffentliche Methoden
    # -------------------------------------------------------------------------
    def set_engine(self, engine_name: str) -> None:
        """Setzt die TTS-Engine (piper, pyttsx3, espeak)."""
        if engine_name in self._available_engines:
            if hasattr(self.settings, 'tts_engine'):
                self.settings.tts_engine = engine_name
            logger.info(f"TTS-Engine auf {engine_name} gesetzt")
        else:
            logger.warning(f"TTS-Engine {engine_name} nicht verfügbar")

    def set_voice(self, voice_name: str) -> None:
        """Setzt die Piper-Stimme (nur für Piper)."""
        self._voice = voice_name
        if hasattr(self.settings, 'tts_voice'):
            self.settings.tts_voice = voice_name

    def set_volume(self, volume: float) -> None:
        """Setzt die Lautstärke (0.0 - 1.0), wo unterstützt."""
        self._volume = max(0.0, min(1.0, volume))

    def is_available(self, engine: Optional[str] = None) -> bool:
        """
        Prüft, ob die konfigurierte (oder eine bestimmte) TTS-Engine verfügbar ist.

        Args:
            engine: Name der Engine (piper, pyttsx3, espeak). Wenn None, wird die aktuelle Einstellung verwendet.
        """
        if engine is None:
            engine = getattr(self.settings, 'tts_engine', 'piper')
        if engine == "piper":
            return shutil.which("piper") is not None and bool(self._available_players)
        elif engine == "pyttsx3":
            return importlib.util.find_spec("pyttsx3") is not None
        elif engine == "espeak":
            return shutil.which("espeak") is not None
        return False

    def test_audio(self, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """Spielt einen kurzen Testton ab (optional)."""
        if shutil.which("speaker-test"):
            try:
                subprocess.run(["speaker-test", "-t", "sine", "-f", "1000", "-l", "1"], timeout=2, check=False)
                if callback:
                    callback(True, "Testton erfolgreich abgespielt")
                return
            except Exception as e:
                logger.debug(f"speaker-test fehlgeschlagen: {e}")
        self.speak("Test. Dies ist ein kurzer Testton.", callback)

    def speak(self, text: str, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """
        Gibt den Text als Sprache aus (asynchron).

        Args:
            text: Der vorzulesende Text.
            callback: Wird nach Abschluss mit (erfolg, nachricht) aufgerufen.
        """
        if not text or not text.strip():
            if callback:
                callback(False, "Leerer Text")
            return

        # Text in Chunks aufteilen, falls zu lang
        chunks = self._split_text(text)
        if len(chunks) > 1:
            logger.info(f"Text in {len(chunks)} Chunks aufgeteilt (max. {self.MAX_CHUNK_LEN} Zeichen pro Chunk)")
            self._speak_chunks(chunks, callback)
            return

        # Einzelner Chunk
        engine = getattr(self.settings, 'tts_engine', 'piper')
        if not self.is_available(engine):
            # Fallback auf verfügbare Engine
            engine = self._fallback_engine()
            if engine is None:
                if callback:
                    callback(False, "Keine TTS-Engine verfügbar (geprüft: piper, pyttsx3, espeak)")
                return
            logger.warning(f"Fallback auf Engine '{engine}'")

        self.stop()
        self._stop_requested.clear()

        if DEBUG_LEVEL >= 3:
            log_debug("tts", f"Starte Sprachausgabe mit Engine '{engine}', {len(text)} Zeichen")

        if engine == "piper":
            self._speak_piper(text, callback)
        elif engine == "pyttsx3":
            self._speak_pyttsx3(text, callback)
        elif engine == "espeak":
            self._speak_espeak(text, callback)
        else:
            if callback:
                callback(False, f"Unbekannte Engine: {engine}")

    def speak_to_file(self, text: str, output_path: str, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """
        Erzeugt eine Audiodatei aus dem Text (asynchron).

        Args:
            text: Der zu sprechende Text.
            output_path: Zielpfad (endet mit .mp3 oder .wav).
            callback: Wird nach Abschluss mit (erfolg, nachricht) aufgerufen.
        """
        if not text or not text.strip():
            if callback:
                callback(False, "Leerer Text")
            return

        file_ext = os.path.splitext(output_path)[1].lower()
        if file_ext not in ('.mp3', '.wav'):
            if callback:
                callback(False, "Nur .mp3 oder .wav werden unterstützt")
            return

        engine = getattr(self.settings, 'tts_engine', 'piper')
        if not self.is_available(engine):
            engine = self._fallback_engine()
            if engine is None:
                if callback:
                    callback(False, "Keine TTS-Engine verfügbar (geprüft: piper, pyttsx3, espeak)")
                return

        if DEBUG_LEVEL >= 3:
            log_debug("tts", f"Starte Datei-Ausgabe mit Engine '{engine}': {output_path}")

        self.stop()

        if engine == "piper":
            self._speak_to_file_piper(text, output_path, callback)
        elif engine == "pyttsx3":
            self._speak_to_file_pyttsx3(text, output_path, callback)
        elif engine == "espeak":
            self._speak_to_file_espeak(text, output_path, callback)
        else:
            if callback:
                callback(False, f"Unbekannte Engine: {engine}")

    def stop(self) -> None:
        """Stoppt die laufende Sprachausgabe sofort."""
        with self._lock:
            if self._process and self._process.poll() is None:
                try:
                    self._process.terminate()
                    self._process.wait(timeout=1.0)
                except subprocess.TimeoutExpired:
                    self._process.kill()
                    self._process.wait(timeout=0.5)
                except Exception as e:
                    logger.warning(f"Fehler beim Beenden des Piper-Prozesses: {e}")
                finally:
                    self._process = None
            self._stop_requested.set()

        if self._forward_thread and self._forward_thread.is_alive():
            if DEBUG_LEVEL >= 3:
                log_debug("tts", "Warte auf Beendigung des forward-Threads...")
            self._forward_thread.join(timeout=1.0)

        # Nur auf den Speaking-Thread warten, wenn es nicht der aktuelle Thread ist
        if self._speaking_thread and self._speaking_thread.is_alive() and self._speaking_thread is not threading.current_thread():
            self._speaking_thread.join(timeout=2.0)

    def dispose(self) -> None:
        """Gibt alle Ressourcen frei (wird beim Programmende aufgerufen)."""
        self.stop()

    # -------------------------------------------------------------------------
    # Hilfsmethoden
    # -------------------------------------------------------------------------
    def _split_text(self, text: str) -> List[str]:
        """
        Teilt einen langen Text in sinnvolle Chunks auf (Sätze oder Wortgruppen).

        Args:
            text: Der zu teilende Text.

        Returns:
            Liste von Text-Chunks.
        """
        if len(text) <= self.MAX_CHUNK_LEN:
            return [text]

        # Versuche, an Satzenden zu teilen
        sentences = re.split(r'(?<=[.!?])\s+', text)
        chunks = []
        current_chunk = ""
        for sent in sentences:
            if len(current_chunk) + len(sent) + 1 <= self.MAX_CHUNK_LEN:
                if current_chunk:
                    current_chunk += " " + sent
                else:
                    current_chunk = sent
            else:
                if current_chunk:
                    chunks.append(current_chunk)
                current_chunk = sent
        if current_chunk:
            chunks.append(current_chunk)
        return chunks

    def _speak_chunks(self, chunks: List[str], callback: Optional[Callable]) -> None:
        """
        Spricht mehrere Text-Chunks nacheinander (iterativ mit Rekursion).

        Args:
            chunks: Liste der Text-Chunks in der Reihenfolge, in der sie gesprochen werden sollen.
            callback: Wird nach Abschluss aller Chunks oder bei Abbruch aufgerufen.
                      Signatur: callback(success: bool, message: str)
                      - success: True, wenn alle Chunks erfolgreich abgespielt wurden.
                      - message: Statusmeldung (z.B. "Alle Chunks abgespielt" oder Fehlermeldung).

        Note:
            Die Methode verwendet eine rekursive Abarbeitung, die bei normalen Texten (max. 2–3 Chunks)
            unkritisch ist. Bei Abbruch (stop_requested) wird die weitere Ausführung beendet.
        """
        if not chunks:
            if callback:
                callback(False, "Keine Chunks zum Abspielen")
            return

        def play_next(index: int):
            if index >= len(chunks) or self._stop_requested.is_set():
                if callback:
                    msg = "Alle Chunks abgespielt" if not self._stop_requested.is_set() else "Abgebrochen"
                    callback(not self._stop_requested.is_set(), msg)
                return

            if DEBUG_LEVEL >= 3:
                log_debug("tts", f"Spiele Chunk {index+1}/{len(chunks)} ({len(chunks[index])} Zeichen)")

            def chunk_callback(success: bool, message: str):
                if success:
                    # Nächsten Chunk mit 50 ms Verzögerung starten
                    threading.Timer(0.05, lambda: play_next(index + 1)).start()
                else:
                    if callback:
                        callback(False, f"Fehler in Chunk {index+1}: {message}")

            self.speak(chunks[index], callback=chunk_callback)

        play_next(0)

    def _fallback_engine(self) -> Optional[str]:
        """Gibt die erste verfügbare Engine zurück (priorisiert piper, pyttsx3, espeak)."""
        for eng in ["piper", "pyttsx3", "espeak"]:
            if self.is_available(eng):
                return eng
        return None

    # -------------------------------------------------------------------------
    # Piper‑Implementierung (binär)
    # -------------------------------------------------------------------------
    def _get_piper_cache_dir(self) -> str:
        """Ermittelt das plattformunabhängige Cache-Verzeichnis für Piper-Modelle."""
        if IS_WINDOWS:
            base = os.environ.get("APPDATA", os.path.expanduser("~\\AppData\\Roaming"))
            return os.path.join(base, "piper")
        else:
            base = os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache"))
            return os.path.join(base, "piper")

    def _get_audio_player_command(self, fallback_index: int = 0) -> Tuple[str, List[str]]:
        """Holt den Befehl für den Audio-Player mit Fallback (bei Fehlern)."""
        if fallback_index >= len(self._available_players):
            return None, None
        return self._available_players[fallback_index]

    def _speak_piper(self, text: str, callback: Optional[Callable]) -> None:
        """Interne Methode für Piper mit Audio‑Player (asynchron)."""
        def worker():
            process = None
            audio_player = None
            player_index = 0
            success = False
            message = "Unbekannter Fehler"
            forwarded_bytes = 0
            use_volume_scaling = self._volume != 1.0

            if NUMPY_AVAILABLE:
                import numpy as np
                _NP_AVAILABLE = True
            else:
                _NP_AVAILABLE = False

            try:
                piper_exe = shutil.which("piper")
                if not piper_exe:
                    venv_bin = os.path.join(os.path.dirname(sys.executable), "bin", "piper")
                    if os.path.exists(venv_bin):
                        piper_exe = venv_bin
                    else:
                        raise Exception("Piper nicht im PATH gefunden.")

                cache_dir = self._get_piper_cache_dir()
                model_file = f"{self._voice}.onnx"
                model_path = os.path.join(cache_dir, model_file)
                if not os.path.exists(model_path):
                    model_path = self._voice

                cmd = [
                    piper_exe,
                    "--model", model_path,
                    "--length_scale", str(self._length_scale),
                    "--sentence_silence", str(self._sentence_silence),
                    "--output-raw",
                ]
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", f"Starte Piper: {' '.join(cmd)}")
                process = subprocess.Popen(
                    cmd,
                    stdin=subprocess.PIPE,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                )
                with self._lock:
                    self._process = process

                while player_index < len(self._available_players):
                    player_name, player_cmd = self._get_audio_player_command(player_index)
                    if DEBUG_LEVEL >= 3:
                        log_debug("tts", f"Versuche Audio-Player: {player_name} mit Befehl {player_cmd}")
                    audio_player = subprocess.Popen(
                        player_cmd,
                        stdin=subprocess.PIPE,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                    )
                    time.sleep(0.1)
                    if audio_player.poll() is None:
                        break
                    else:
                        logger.warning(f"Audio-Player {player_name} startete nicht, versuche nächsten")
                        player_index += 1
                        audio_player = None
                if audio_player is None:
                    raise Exception("Kein Audio-Player konnte gestartet werden")

                process.stdin.write(text.encode("utf-8"))
                process.stdin.close()

                forward_stop = threading.Event()
                forward_event = threading.Event()
                error_in_forward = None

                def forward():
                    nonlocal forwarded_bytes, error_in_forward
                    try:
                        start_time = time.time()
                        while not forward_stop.is_set():
                            # Mit Timeout lesen? read blockiert. Wir verwenden einen separaten Thread,
                            # daher reicht es, den Stop zu prüfen, aber wenn keine Daten kommen,
                            # blockiert read. Daher setzen wir später die Pipe zu.
                            chunk = process.stdout.read(8192)
                            if not chunk:
                                break
                            if forwarded_bytes == 0 and time.time() - start_time > 3.0:
                                error_in_forward = TimeoutError("Piper liefert keine Audiodaten")
                                break

                            if use_volume_scaling and chunk:
                                if _NP_AVAILABLE:
                                    data = np.frombuffer(chunk, dtype=np.int16).astype(np.float32)
                                    data *= self._volume
                                    np.clip(data, -32768, 32767, out=data)
                                    chunk = data.astype(np.int16).tobytes()
                                else:
                                    import struct
                                    num_samples = len(chunk) // 2
                                    fmt = f'<{num_samples}h'
                                    samples = struct.unpack(fmt, chunk)
                                    scaled = tuple(int(max(-32768, min(32767, s * self._volume))) for s in samples)
                                    chunk = struct.pack(fmt, *scaled)

                            if audio_player.stdin:
                                try:
                                    audio_player.stdin.write(chunk)
                                    forwarded_bytes += len(chunk)
                                except BrokenPipeError:
                                    logger.warning("Audio‑Player-Pipe unterbrochen")
                                    break
                    except Exception as e:
                        error_in_forward = e
                        logger.error(f"Fehler in forward: {e}")
                    finally:
                        if audio_player and audio_player.stdin and not audio_player.stdin.closed:
                            try:
                                audio_player.stdin.close()
                            except Exception:
                                pass
                        forward_event.set()

                self._forward_thread = threading.Thread(target=forward, daemon=True, name="TTS-Forward")
                self._forward_thread.start()

                try:
                    process.wait(timeout=30)
                except subprocess.TimeoutExpired:
                    logger.warning("Piper läuft länger als 30 Sekunden – wird abgebrochen")
                    process.kill()
                    process.wait()

                # Wichtig: stdout-Pipe schließen, damit forward-Thread aus read() kommt
                if process.stdout and not process.stdout.closed:
                    try:
                        process.stdout.close()
                    except Exception:
                        pass

                forward_stop.set()
                # Kurz warten, damit forward-Thread die Chance hat, die geschlossene Pipe zu bemerken
                time.sleep(0.1)
                # Auf den Forward-Thread warten, aber nicht ewig
                forward_event.wait(timeout=2.0)
                if self._forward_thread.is_alive():
                    if DEBUG_LEVEL >= 3:
                        log_debug("tts", "Forward-Thread läuft noch, warte...")
                    self._forward_thread.join(timeout=2.0)
                    if self._forward_thread.is_alive():
                        logger.warning("Forward-Thread beendet sich nicht – möglicherweise hängen geblieben")
                self._forward_thread = None

                if audio_player:
                    try:
                        audio_player.wait(timeout=2.0)
                    except subprocess.TimeoutExpired:
                        audio_player.terminate()
                        audio_player.wait(timeout=0.5)

                stderr = process.stderr.read().decode("utf-8", errors="ignore")
                if error_in_forward:
                    raise error_in_forward
                if process.returncode == 0 and forwarded_bytes > 0:
                    success = True
                    message = ""
                    if DEBUG_LEVEL >= 3:
                        log_debug("tts", f"Piper erfolgreich, {forwarded_bytes} Bytes an Player gesendet")
                else:
                    message = f"Piper beendet mit Code {process.returncode}, forwarded_bytes={forwarded_bytes}, stderr: {stderr[:200]}"
                    logger.error(message)

            except Exception as e:
                message = str(e)
                logger.exception(f"Fehler in Piper-Worker: {e}")
            finally:
                if process and process.poll() is None:
                    try:
                        process.kill()
                    except Exception:
                        pass
                if audio_player and audio_player.poll() is None:
                    try:
                        audio_player.terminate()
                        audio_player.wait(timeout=1.0)
                    except Exception:
                        pass
                with self._lock:
                    if self._process == process:
                        self._process = None
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-Piper")
        self._speaking_thread.start()

    def _speak_to_file_piper(self, text: str, output_path: str, callback: Optional[Callable]) -> None:
        """Interne Methode zum Erzeugen einer Audiodatei mit Piper."""
        def worker():
            temp_path = None
            success = False
            message = ""
            try:
                piper_exe = shutil.which("piper")
                if not piper_exe:
                    venv_bin = os.path.join(os.path.dirname(sys.executable), "bin", "piper")
                    if os.path.exists(venv_bin):
                        piper_exe = venv_bin
                    else:
                        raise Exception("Piper nicht im PATH gefunden.")

                cache_dir = self._get_piper_cache_dir()
                model_file = f"{self._voice}.onnx"
                model_path = os.path.join(cache_dir, model_file)
                if not os.path.exists(model_path):
                    model_path = self._voice

                need_conversion = output_path.lower().endswith('.mp3')
                if need_conversion:
                    temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
                    temp_path = temp_wav.name
                    temp_wav.close()
                    output_wav = temp_path
                else:
                    output_wav = output_path

                cmd = [
                    piper_exe,
                    "--model", model_path,
                    "--length_scale", str(self._length_scale),
                    "--sentence_silence", str(self._sentence_silence),
                    "--output_file", output_wav,
                ]
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", f"Piper Datei-Ausgabe: {' '.join(cmd)}")
                proc = subprocess.run(
                    cmd,
                    input=text,
                    capture_output=True,
                    text=True,
                    timeout=60,
                    encoding="utf-8"
                )
                if proc.returncode != 0:
                    raise Exception(f"Piper Fehler (Code {proc.returncode}): {proc.stderr[:200]}")

                if need_conversion:
                    if not shutil.which("ffmpeg"):
                        raise Exception("ffmpeg nicht gefunden – kann keine MP3 erzeugen")
                    conv_cmd = ["ffmpeg", "-i", output_wav, "-y", output_path]
                    conv_proc = subprocess.run(conv_cmd, capture_output=True, text=True)
                    if conv_proc.returncode != 0:
                        raise Exception(f"ffmpeg Fehler: {conv_proc.stderr[:200]}")

                success = True
                message = f"Gespeichert unter {output_path}"
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", message)
            except Exception as e:
                message = str(e)
                logger.exception(f"Fehler in speak_to_file: {e}")
            finally:
                if temp_path and os.path.exists(temp_path):
                    try:
                        os.unlink(temp_path)
                    except Exception:
                        pass
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-Piper-File")
        self._speaking_thread.start()

    # -------------------------------------------------------------------------
    # pyttsx3‑Implementierung (Fallback)
    # -------------------------------------------------------------------------
    def _speak_pyttsx3(self, text: str, callback: Optional[Callable]) -> None:
        """Interne Methode für pyttsx3 (blockierend, läuft in eigenem Thread)."""
        def worker():
            success = False
            message = ""
            engine = None
            try:
                import pyttsx3
                engine = pyttsx3.init()
                if self._volume != 1.0:
                    engine.setProperty('volume', self._volume)
                engine.setProperty('rate', 150)
                engine.say(text)
                engine.runAndWait()
                success = True
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", "pyttsx3 erfolgreich abgespielt")
            except Exception as e:
                message = str(e)
                logger.error(f"Fehler bei pyttsx3: {e}")
            finally:
                if engine:
                    try:
                        engine.stop()
                    except Exception:
                        pass
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-pyttsx3")
        self._speaking_thread.start()

    def _speak_to_file_pyttsx3(self, text: str, output_path: str, callback: Optional[Callable]) -> None:
        """Interne Methode zum Erzeugen einer Audiodatei mit pyttsx3."""
        def worker():
            success = False
            message = ""
            try:
                import pyttsx3
                engine = pyttsx3.init()
                if self._volume != 1.0:
                    engine.setProperty('volume', self._volume)
                engine.setProperty('rate', 150)
                temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
                temp_wav.close()
                engine.save_to_file(text, temp_wav.name)
                engine.runAndWait()

                if output_path.lower().endswith('.mp3'):
                    if not shutil.which("ffmpeg"):
                        message = "ffmpeg nicht gefunden – kann keine MP3 erzeugen"
                        raise Exception(message)
                    subprocess.run(["ffmpeg", "-i", temp_wav.name, "-y", output_path], check=True)
                else:
                    shutil.copy2(temp_wav.name, output_path)
                success = True
                message = f"Gespeichert unter {output_path}"
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", message)
            except Exception as e:
                message = str(e)
                logger.exception(f"Fehler in pyttsx3 speak_to_file: {e}")
            finally:
                if 'temp_wav' in locals() and os.path.exists(temp_wav.name):
                    try:
                        os.unlink(temp_wav.name)
                    except Exception:
                        pass
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-pyttsx3-File")
        self._speaking_thread.start()

    # -------------------------------------------------------------------------
    # espeak‑Implementierung (leichtgewichtige Alternative)
    # -------------------------------------------------------------------------
    def _speak_espeak(self, text: str, callback: Optional[Callable]) -> None:
        """Interne Methode für espeak (über subprocess)."""
        def worker():
            success = False
            message = ""
            try:
                cmd = ["espeak", "-v", "de", "-p", "50", "-s", "150"]
                if self._volume != 1.0:
                    amp = int(100 * self._volume)
                    cmd.extend(["-a", str(amp)])
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", f"Starte espeak: {' '.join(cmd)}")
                proc = subprocess.run(cmd, input=text, capture_output=True, text=True, timeout=30)
                if proc.returncode == 0:
                    success = True
                    message = ""
                else:
                    message = f"espeak beendet mit Code {proc.returncode}: {proc.stderr[:200]}"
                    logger.error(message)
            except Exception as e:
                message = str(e)
                logger.exception(f"Fehler in espeak-Worker: {e}")
            finally:
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-espeak")
        self._speaking_thread.start()

    def _speak_to_file_espeak(self, text: str, output_path: str, callback: Optional[Callable]) -> None:
        """Interne Methode zum Erzeugen einer Audiodatei mit espeak (über WAV-Ausgabe)."""
        def worker():
            success = False
            message = ""
            try:
                temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
                temp_wav.close()
                cmd = ["espeak", "-v", "de", "-w", temp_wav.name, "-p", "50", "-s", "150"]
                if self._volume != 1.0:
                    amp = int(100 * self._volume)
                    cmd.extend(["-a", str(amp)])
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", f"Starte espeak Datei-Ausgabe: {' '.join(cmd)}")
                proc = subprocess.run(cmd, input=text, capture_output=True, text=True, timeout=30)
                if proc.returncode != 0:
                    raise Exception(f"espeak Fehler (Code {proc.returncode}): {proc.stderr[:200]}")

                if output_path.lower().endswith('.mp3'):
                    if not shutil.which("ffmpeg"):
                        raise Exception("ffmpeg nicht gefunden – kann keine MP3 erzeugen")
                    subprocess.run(["ffmpeg", "-i", temp_wav.name, "-y", output_path], check=True)
                else:
                    shutil.copy2(temp_wav.name, output_path)
                success = True
                message = f"Gespeichert unter {output_path}"
                if DEBUG_LEVEL >= 3:
                    log_debug("tts", message)
            except Exception as e:
                message = str(e)
                logger.exception(f"Fehler in espeak speak_to_file: {e}")
            finally:
                if 'temp_wav' in locals() and os.path.exists(temp_wav.name):
                    try:
                        os.unlink(temp_wav.name)
                    except Exception:
                        pass
                if callback:
                    callback(success, message)
                self._speaking_thread = None

        self._speaking_thread = threading.Thread(target=worker, daemon=True, name="TTS-espeak-File")
        self._speaking_thread.start()


class DarkMessageBox:
    __slots__ = ()

    @classmethod
    def showinfo(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                 timeout: Optional[int] = None) -> Optional[bool]:
        return cls._show_dialog(title, message, "info", parent, timeout=timeout)

    @classmethod
    def showwarning(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                    timeout: Optional[int] = None) -> Optional[bool]:
        return cls._show_dialog(title, message, "warning", parent, timeout=timeout)

    @classmethod
    def showerror(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                  timeout: Optional[int] = None) -> Optional[bool]:
        return cls._show_dialog(title, message, "error", parent, timeout=timeout)

    @classmethod
    def askokcancel(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                    timeout: Optional[int] = None) -> Optional[bool]:
        return cls._show_dialog(title, message, "question", parent, buttons=True, timeout=timeout)

    @classmethod
    def askyesno(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                 timeout: Optional[int] = None) -> Optional[bool]:
        return cls._ask_yesno(title, message, parent, timeout=timeout)

    @classmethod
    def show_progress(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                      indeterminate: bool = True) -> Any:
        if threading.current_thread() is not threading.main_thread():
            warnings.warn("DarkMessageBox.show_progress wurde nicht im Hauptthread aufgerufen. "
                          "GUI-Updates können fehlschlagen.", RuntimeWarning, stacklevel=2)

        def _create():
            nonlocal dialog, progress, message_label
            try:
                root = parent if parent and parent.winfo_exists() else tk._default_root
                if not root or not root.winfo_exists():
                    logger.error("Kein gültiges root-Fenster für ProgressDialog")
                    return
                dlg = tk.Toplevel(root)
                dlg.title(f"🐉 {title}")
                dlg.configure(bg=CURRENT_THEME.BG_PRIMARY)
                dlg.resizable(False, False)
                dlg.transient(root)
                dlg.grab_set()
                main = tk.Frame(dlg, bg=CURRENT_THEME.BG_PRIMARY, padx=30, pady=25)
                main.pack(fill="both", expand=True)
                msg_lbl = tk.Label(main, text=message, font=Fonts.PRIMARY,
                                    bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY,
                                    justify="center")
                msg_lbl.pack(pady=(0, 20))
                prog = ttk.Progressbar(main, mode="indeterminate" if indeterminate else "determinate", length=300)
                prog.pack(pady=(0, 10))
                prog.start(10)
                cls._center_dialog(dlg, root)
                dialog = dlg
                progress = prog
                message_label = msg_lbl
            except (tk.TclError, RuntimeError) as e:
                logger.warning(f"⚠️ Progress Dialog Error: {e}")

        dialog = None
        progress = None
        message_label = None
        _create()

        class ProgressController:
            __slots__ = ("dialog", "progress", "_message_label")
            def __init__(self):
                self.dialog = dialog
                self.progress = progress
                self._message_label = message_label
            def close(self) -> None:
                if self.dialog and self.dialog.winfo_exists():
                    try:
                        if self.progress:
                            self.progress.stop()
                        self.dialog.destroy()
                    except Exception:
                        pass
                self.dialog = None
                self.progress = None
                self._message_label = None
            def update_message(self, new_message: str) -> None:
                if self.dialog and self.dialog.winfo_exists() and self._message_label:
                    try:
                        self._message_label.config(text=new_message)
                    except Exception:
                        pass
        return ProgressController()

    @classmethod
    def _show_dialog(cls, title: str, message: str, msg_type: str,
                     parent: Optional[tk.Tk] = None, buttons: bool = False,
                     timeout: Optional[int] = None) -> Optional[bool]:
        try:
            parent = cls._resolve_parent(parent)
            if parent is None:
                return cls._fallback_messagebox(title, message, msg_type, buttons)
            dialog, result, timeout_id = cls._create_base_dialog(parent, title, msg_type, message, timeout=timeout)
            if buttons:
                cls._add_ok_cancel_buttons(dialog, result, timeout_id, title)
            else:
                cls._add_ok_button(dialog, result, timeout_id)
            dialog.protocol("WM_DELETE_WINDOW",
                            lambda: (cls._cancel_timeout(dialog, timeout_id),
                                     cls._on_closing(result, False if buttons else True)))
            cls._center_dialog(dialog, parent)
            parent.wait_window(dialog)
            return result["value"]
        except (tk.TclError, RuntimeError, AttributeError) as e:
            logger.warning(f"⚠️ DarkMessageBox Error: {e}")
            return cls._fallback_messagebox(title, message, msg_type, buttons)

    @classmethod
    def _ask_yesno(cls, title: str, message: str, parent: Optional[tk.Tk] = None,
                   timeout: Optional[int] = None) -> Optional[bool]:
        try:
            parent = cls._resolve_parent(parent)
            if parent is None:
                import tkinter.messagebox as mb
                return mb.askyesno(title, message)
            dialog, result, timeout_id = cls._create_base_dialog(parent, title, "question", message, icon_only=True, timeout=timeout)
            btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
            btn_frame.pack(fill="x", pady=(10, 0))

            def set_res(val: bool):
                cls._cancel_timeout(dialog, timeout_id)
                result["value"] = val
                if dialog.winfo_exists():
                    dialog.destroy()

            yes_btn = tk.Button(btn_frame, text="  👍 Ja  ", command=lambda: set_res(True),
                                 bg=CURRENT_THEME.SUCCESS, fg=CURRENT_THEME.TEXT_PRIMARY,
                                 font=("Segoe UI", 10, "bold"), relief="flat", padx=25, pady=10, cursor="hand2")
            yes_btn.pack(side="left", expand=True, padx=(0, 10))
            no_btn = tk.Button(btn_frame, text="  👎 Nein  ", command=lambda: set_res(False),
                                bg=CURRENT_THEME.ERROR, fg=CURRENT_THEME.TEXT_PRIMARY,
                                font=("Segoe UI", 10, "bold"), relief="flat", padx=25, pady=10, cursor="hand2")
            no_btn.pack(side="right", expand=True)
            dialog.bind("<Return>", lambda e: set_res(True))
            dialog.bind("<Escape>", lambda e: set_res(False))
            dialog.bind("y", lambda e: set_res(True))
            dialog.bind("n", lambda e: set_res(False))
            yes_btn.focus_set()
            dialog.protocol("WM_DELETE_WINDOW", lambda: (cls._cancel_timeout(dialog, timeout_id), set_res(False)))
            cls._center_dialog(dialog, parent)
            parent.wait_window(dialog)
            return result["value"]
        except (tk.TclError, RuntimeError, AttributeError):
            import tkinter.messagebox as mb
            return mb.askyesno(title, message)

    @classmethod
    def _create_base_dialog(cls, parent: tk.Tk, title: str, msg_type: str, message: str,
                            icon_only: bool = False, timeout: Optional[int] = None) -> tuple:
        dialog = tk.Toplevel(parent)
        dialog.title(f"🐉 {title}" if not title.startswith("🐉") else title)
        dialog.configure(bg=CURRENT_THEME.BG_PRIMARY)
        dialog.resizable(False, False)
        dialog.transient(parent)
        dialog.grab_set()

        if timeout is not None:
            timeout_id = dialog.after(timeout * 1000, lambda: cls._auto_close_dialog(dialog, title))
        else:
            timeout_id = None

        main = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY, padx=25, pady=25)
        main.pack(fill="both", expand=True)

        if icon_only:
            icon_label = tk.Label(main, text="❓", font=("Segoe UI", 28),
                                    bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_ACCENT)
            icon_label.pack(pady=(0, 20))
            msg = tk.Label(main, text=message, font=Fonts.PRIMARY,
                            bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY,
                            justify="center", wraplength=350)
            msg.pack(pady=(0, 30))
        else:
            content = tk.Frame(main, bg=CURRENT_THEME.BG_PRIMARY)
            content.pack(fill="both", expand=True, pady=(0, 20))
            icon_frame = tk.Frame(content, bg=CURRENT_THEME.BG_PRIMARY, width=60)
            icon_frame.pack(side="left", fill="y")
            icon_frame.pack_propagate(False)
            icons = {
                "info": ("ℹ️", CURRENT_THEME.TEXT_ACCENT),
                "warning": ("⚠️", CURRENT_THEME.WARNING),
                "error": ("❌", CURRENT_THEME.ERROR),
                "question": ("❓", CURRENT_THEME.TEXT_ACCENT),
                "success": ("✅", CURRENT_THEME.SUCCESS),
            }
            icon_char, icon_color = icons.get(msg_type, ("💬", CURRENT_THEME.TEXT_PRIMARY))
            tk.Label(icon_frame, text=icon_char, font=("Segoe UI", 24),
                     bg=CURRENT_THEME.BG_PRIMARY, fg=icon_color).pack(expand=True)
            msg_frame = tk.Frame(content, bg=CURRENT_THEME.BG_PRIMARY)
            msg_frame.pack(side="left", fill="both", expand=True, padx=(20, 0))
            if len(title) > 30:
                tk.Label(msg_frame, text=title, font=Fonts.SUBTITLE,
                         bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY,
                         justify="left", anchor="w").pack(anchor="w", pady=(0, 10))
            tk.Label(msg_frame, text=message, font=Fonts.PRIMARY,
                     bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY,
                     justify="left", wraplength=350, anchor="w").pack(fill="x", expand=True, anchor="w")

        result = {"value": None}
        return dialog, result, timeout_id

    @classmethod
    def _add_ok_button(cls, dialog: tk.Toplevel, result: dict, timeout_id: Optional[str]) -> tk.Frame:
        btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x")

        def on_ok():
            cls._cancel_timeout(dialog, timeout_id)
            result["value"] = True
            if dialog.winfo_exists():
                dialog.destroy()

        ok_btn = tk.Button(btn_frame, text="OK", command=on_ok,
                           bg=CURRENT_THEME.SUCCESS, fg=CURRENT_THEME.TEXT_PRIMARY,
                           font=Fonts.BUTTON, relief="flat", padx=25, pady=8, cursor="hand2", takefocus=True)
        ok_btn.pack(side="right")
        ok_btn.focus_set()
        dialog.bind("<Return>", lambda e: on_ok())
        dialog.bind("<Escape>", lambda e: on_ok())
        dialog.bind("<space>", lambda e: on_ok())
        return btn_frame

    @classmethod
    def _add_ok_cancel_buttons(cls, dialog: tk.Toplevel, result: dict, timeout_id: Optional[str], title: str) -> tk.Frame:
        btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x")

        def set_result(val: bool):
            cls._cancel_timeout(dialog, timeout_id)
            result["value"] = val
            if dialog.winfo_exists():
                dialog.destroy()

        cancel_btn = tk.Button(btn_frame, text="Abbrechen", command=lambda: set_result(False),
                                bg=CURRENT_THEME.BG_TERTIARY, fg=CURRENT_THEME.TEXT_PRIMARY,
                                font=Fonts.BUTTON, relief="flat", padx=22, pady=8, cursor="hand2", takefocus=True)
        cancel_btn.pack(side="right", padx=(10, 0))
        ok_btn = tk.Button(btn_frame, text="OK", command=lambda: set_result(True),
                           bg=CURRENT_THEME.SUCCESS, fg=CURRENT_THEME.TEXT_PRIMARY,
                           font=Fonts.BUTTON, relief="flat", padx=25, pady=8, cursor="hand2", takefocus=True)
        ok_btn.pack(side="right")
        dialog.bind("<Return>", lambda e: set_result(True))
        dialog.bind("<Escape>", lambda e: set_result(False))
        dialog.bind("<space>", lambda e: cancel_btn.focus_set())
        is_exit = any(w in title.lower() for w in ["beenden", "exit", "quit", "schließen"])
        if is_exit:
            cancel_btn.focus_set()
        else:
            ok_btn.focus_set()
        return btn_frame

    @staticmethod
    def _resolve_parent(parent: Optional[tk.Tk]) -> Optional[tk.Tk]:
        if parent and parent.winfo_exists():
            return parent
        if tk._default_root and tk._default_root.winfo_exists():
            return tk._default_root
        return None

    @staticmethod
    def _center_dialog(dialog: tk.Toplevel, parent: Optional[tk.Tk]) -> None:
        try:
            dialog.update_idletasks()

            # Fenstergröße robust bestimmen
            dlg_w = dialog.winfo_width()
            dlg_h = dialog.winfo_height()

            # Fallback falls Tkinter noch nicht korrekt gemessen hat
            if dlg_w <= 1 or dlg_h <= 1:
                dlg_w = dialog.winfo_reqwidth()
                dlg_h = dialog.winfo_reqheight()

            if parent is None or not parent.winfo_exists():
                # Fallback: zentriert auf dem Bildschirm
                screen_w = dialog.winfo_screenwidth()
                screen_h = dialog.winfo_screenheight()

                x = (screen_w - dlg_w) // 2
                y = (screen_h - dlg_h) // 2

            else:
                parent.update_idletasks()

                parent_x = parent.winfo_rootx()
                parent_y = parent.winfo_rooty()
                parent_w = parent.winfo_width()
                parent_h = parent.winfo_height()

                x = parent_x + (parent_w - dlg_w) // 2
                y = parent_y + (parent_h - dlg_h) // 2

                screen_w = parent.winfo_screenwidth()
                screen_h = parent.winfo_screenheight()

                # Clamp innerhalb Bildschirm
                x = max(10, min(x, screen_w - dlg_w - 10))
                y = max(10, min(y, screen_h - dlg_h - 10))

            dialog.geometry(f"+{x}+{y}")
            dialog.lift()

            try:
                dialog.focus_set()
            except Exception:
                pass

        except Exception as e:
            logger.debug(f"Dialog-Centering fehlgeschlagen: {e}")

    @staticmethod
    def _auto_close_dialog(dialog: tk.Toplevel, title: str) -> None:
        try:
            if dialog and dialog.winfo_exists():
                logger.warning(f"⚠️ Dialog Timeout: '{title}'")
                dialog.destroy()
        except tk.TclError:
            pass

    @staticmethod
    def _cancel_timeout(dialog: tk.Toplevel, timeout_id: Optional[str]) -> None:
        if timeout_id is not None:
            try:
                dialog.after_cancel(timeout_id)
            except Exception:
                pass

    @staticmethod
    def _on_closing(result: dict, close_val: bool) -> None:
        result["value"] = close_val

    @staticmethod
    def _fallback_messagebox(title: str, message: str, msg_type: str, buttons: bool = False) -> Optional[bool]:
        try:
            import tkinter.messagebox as mb
            if buttons:
                return mb.askokcancel(title, message)
            getattr(mb, f"show{msg_type}")(title, message)
            return None
        except Exception:
            logger.info(f"💬 {title}: {message}")
            return False if buttons else None


class ToolTip:
    def __init__(self, widget: tk.Widget, text: str, delay: int = 500) -> None:
        self.widget = widget
        self.text = text
        self.delay = delay
        self.tip_window: Optional[tk.Toplevel] = None
        self.after_id: Optional[str] = None
        widget.bind("<Enter>", self.enter)
        widget.bind("<Leave>", self.leave)
        widget.bind("<ButtonPress>", self.leave)

    def enter(self, event: Optional[tk.Event] = None) -> None:
        self.schedule()

    def leave(self, event: Optional[tk.Event] = None) -> None:
        self.unschedule()
        self.hide_tip()

    def schedule(self) -> None:
        self.unschedule()
        self.after_id = self.widget.after(self.delay, self.show_tip)

    def unschedule(self) -> None:
        if self.after_id:
            self.widget.after_cancel(self.after_id)
            self.after_id = None

    def show_tip(self) -> None:
        if self.tip_window or not self.text:
            return
        x, y = self.widget.winfo_pointerxy()
        x += 10
        y += 10
        self.tip_window = tw = tk.Toplevel(self.widget)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}")
        label = tk.Label(tw, text=self.text, background="#ffffe0",
                         relief="solid", borderwidth=1, font=("Segoe UI", 9))
        label.pack()
        tw.bind("<Leave>", lambda e: self.hide_tip())

    def hide_tip(self) -> None:
        if self.tip_window:
            try:
                self.tip_window.destroy()
            except tk.TclError:
                pass
            self.tip_window = None


class StatisticsDialog(BaseDialog):
    def __init__(self, parent: tk.Tk, stats_text: str):
        self.stats_text = stats_text
        super().__init__(parent, "Performance Statistics", width=750, height=600, modal=True)

    def build_ui(self) -> None:
        text_widget = scrolledtext.ScrolledText(
            self.main,
            wrap=tk.WORD,
            font=Fonts.MONOSPACE,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            insertbackground=CURRENT_THEME.TEXT_PRIMARY,
            selectbackground=CURRENT_THEME.COMBO_SELECTION,
            selectforeground=CURRENT_THEME.TEXT_PRIMARY,
            padx=10,
            pady=10,
        )
        text_widget.pack(fill="both", expand=True, pady=(0, 10))
        text_widget.insert("1.0", self.stats_text)
        text_widget.config(state="disabled")
        ContextMenuMixin(text_widget)

        btn_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x", pady=(0, 5))

        copy_btn = tk.Button(
            btn_frame,
            text="📋 In Zwischenablage kopieren",
            command=self._copy_to_clipboard,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        copy_btn.pack(side="left", padx=5)

        save_btn = tk.Button(
            btn_frame,
            text="💾 Als Datei speichern",
            command=self._save_to_file,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        save_btn.pack(side="left", padx=5)

        close_btn = tk.Button(
            btn_frame,
            text="Schließen",
            command=self.close,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        close_btn.pack(side="right", padx=5)

        self._text_widget = text_widget

    def _copy_to_clipboard(self) -> None:
        try:
            self.dialog.clipboard_clear()
            self.dialog.clipboard_append(self.stats_text)
            if hasattr(self, "status_label"):
                self.status_label.config(text="✅ In Zwischenablage kopiert")
            else:
                DarkMessageBox.showinfo("Kopiert", "Statistik wurde in die Zwischenablage kopiert.", self.dialog, timeout=2)
        except Exception as e:
            logger.warning(f"Fehler beim Kopieren: {e}")

    def _save_to_file(self) -> None:
        from tkinter import filedialog
        filename = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text files", "*.txt"), ("All files", "*.*")],
            title="Statistik speichern",
            initialfile=f"dragon_stats_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt",
        )
        if filename:
            try:
                with open(filename, "w", encoding="utf-8") as f:
                    f.write(self.stats_text)
                DarkMessageBox.showinfo("Gespeichert", f"Statistik gespeichert:\n{filename}", self.dialog, timeout=2)
            except Exception as e:
                DarkMessageBox.showerror("Fehler", f"Speichern fehlgeschlagen:\n{e}", self.dialog)


class SummarizeDialog(BaseDialog):
    """
    Dialog zur Zusammenfassung von Texten mit Ollama.

    Diese Klasse erstellt einen modalen Dialog, in dem der Benutzer ein Ollama-Modell
    auswählen, die Temperatur einstellen und optional einen Videotitel als Kontext
    einbeziehen kann. Der Text wird in einer Zusammenfassung ausgegeben, die kopiert,
    gespeichert oder übersetzt werden kann.

    Features:
        - Unterstützt große Texte durch automatische Aufteilung in Chunks
        - Asynchrone Verarbeitung mit Thread-Pool und Abbruchmöglichkeit
        - Sprachauswahl für die Zusammenfassung (Deutsch, Englisch, Spanisch, Koreanisch, Chinesisch)
        - Integration des Videotitels als Kontext (falls verfügbar)
        - Zusammenfassung kann kopiert, als Datei gespeichert oder übersetzt werden
        - Fortschrittsanzeige und Statusmeldungen
        - Saubere Ressourcenfreigabe beim Schließen

    Attributes:
        text (str): Der zu zusammenfassende Text.
        gui (DragonWhispererGUI): Referenz auf die Haupt-GUI für Zugriff auf Einstellungen.
        stream_title (Optional[str]): Titel des aktuellen Streams (falls vorhanden).
        summarizer (OllamaSummarizer): Die Ollama-Instanz für die Zusammenfassung.
        _request_cancel (threading.Event): Event zum Abbrechen der Verarbeitung.
        _destroyed (bool): Flag, ob der Dialog bereits zerstört wurde (für thread-sichere GUI-Updates).
    """

    def __init__(self, parent: Any, text: str, gui_ref: Any) -> None:
        """
        Initialisiert den Zusammenfassungs-Dialog.

        Args:
            parent: Das Eltern-Widget (normalerweise das Hauptfenster).
            text: Der zu zusammenfassende Text.
            gui_ref: Referenz auf die Haupt-GUI (für Einstellungen und Stream-Titel).
        """
        self.text = text
        self.gui = gui_ref
        self.stream_title = None

        # 1. Versuch: current_stream_info (während aktiver Verarbeitung)
        if self.gui and hasattr(self.gui, 'current_stream_info') and self.gui.current_stream_info:
            self.stream_title = self.gui.current_stream_info.title

        # 2. Versuch: last_stream_title (nach Ende des Streams)
        if not self.stream_title and self.gui and hasattr(self.gui, 'last_stream_title') and self.gui.last_stream_title:
            self.stream_title = self.gui.last_stream_title

        # 3. Versuch: Text aus dem GUI‑Label extrahieren (falls vorhanden)
        if not self.stream_title and hasattr(self.gui, 'stream_title_label'):
            try:
                label_text = self.gui.stream_title_label.cget("text")
                if label_text and label_text.startswith("📡 "):
                    self.stream_title = label_text[2:].strip()
            except Exception:
                pass

        # 4. Fallback: leeren String setzen, falls gar nichts gefunden wurde
        if not self.stream_title:
            self.stream_title = ""

        self._request_cancel = threading.Event()
        self.summarizer = OllamaSummarizer(
            parent,
            model=self.gui.advanced_settings.summarize_model,
            host=self.gui.advanced_settings.ollama_host,
            cache_manager=self.gui.app_context.cache_manager
        )

        # Temporär gespeicherte Einstellungen (werden beim Schließen zurückgeschrieben)
        self.saved_temp = self.gui.advanced_settings.summarize_temperature
        self.saved_model = self.gui.advanced_settings.summarize_model

        # Status-Variablen für die chunkweise Verarbeitung
        self._chunk_results: List[str] = []
        self._chunks: List[str] = []
        self._current_chunk = 0
        self._prompt = ""
        self._temp = 0.1
        self._destroyed = False

        super().__init__(parent, "Zusammenfassung mit Ollama", width=750, height=650, modal=True)

    def build_ui(self) -> None:
        """Erstellt die Benutzeroberfläche des Dialogs."""
        # Prüfen, ob Ollama erreichbar ist
        if not self.summarizer.is_server_reachable():
            DarkMessageBox.showwarning(
                "Ollama nicht erreichbar",
                "Der Ollama-Server läuft nicht oder ist nicht erreichbar.\n"
                "Bitte starte 'ollama serve' und versuche es erneut.",
                parent=self.parent,
            )
            self.close()
            return

        # 1. Modell-Auswahl
        model_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        model_frame.pack(fill="x", pady=5)

        tk.Label(model_frame, text="Modell:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left")

        self.model_var = tk.StringVar(value=self.saved_model)
        available = self.summarizer.get_available_models()
        if available:
            # Bevorzugte Modelle zuerst
            preferred = ["qwen2.5:7b", "glm4:9b", "llama3.1:8b"]
            values = []
            for pref in preferred:
                if pref in available:
                    values.append(pref)
            for m in available:
                if m not in values:
                    values.append(m)
            self.model_combo = ttk.Combobox(
                model_frame, textvariable=self.model_var, values=values,
                width=20, state="readonly", style="Dark.TCombobox"
            )
            if self.model_var.get() not in values and values:
                self.model_var.set(values[0])
        else:
            self.model_combo = ttk.Combobox(
                model_frame, textvariable=self.model_var,
                values=["(keine Modelle gefunden)"], width=20,
                state="disabled", style="Dark.TCombobox"
            )
            self.model_var.set("(keine Modelle)")
        self.model_combo.pack(side="left", padx=10)
        ToolTip(self.model_combo, "Wähle das Ollama-Modell für die Zusammenfassung")

        # 2. Temperatur (Kreativität)
        tk.Label(model_frame, text="Temperatur:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left", padx=(20,5))
        self.temp_var = tk.DoubleVar(value=self.saved_temp)
        temp_scale = tk.Scale(
            model_frame, from_=0.0, to=1.0, resolution=0.1,
            orient=tk.HORIZONTAL, variable=self.temp_var, length=150,
            bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY,
            highlightbackground=CURRENT_THEME.BG_PRIMARY
        )
        temp_scale.pack(side="left")
        tk.Label(model_frame, text="(0 = deterministisch)", font=("Segoe UI", 7),
                 bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_SECONDARY).pack(side="left", padx=5)
        ToolTip(temp_scale, "Zufälligkeit der Ausgabe (höher = kreativer)")

        # 3. Sprachauswahl für die Zusammenfassung
        lang_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        lang_frame.pack(fill="x", pady=5)
        tk.Label(lang_frame, text="Zusammenfassen auf:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left")
        self.summary_lang_var = tk.StringVar()
        supported_summary_langs = ["Deutsch", "Englisch", "Spanisch", "Koreanisch", "Chinesisch"]
        current_lang_name = SUPPORTED_LANGUAGES.get(self.gui.current_language, "Deutsch")
        if current_lang_name not in supported_summary_langs:
            current_lang_name = "Deutsch"
        self.summary_lang_var.set(current_lang_name)
        lang_combo = ttk.Combobox(
            lang_frame, textvariable=self.summary_lang_var,
            values=supported_summary_langs, width=15,
            state="readonly", style="Dark.TCombobox"
        )
        lang_combo.pack(side="left", padx=10)
        lang_combo.bind("<<ComboboxSelected>>", lambda e: self._set_default_prompt())
        ToolTip(lang_combo, "Sprache der Zusammenfassung")

        # 4. Checkbox für Videotitel als Kontext
        self.use_title_var = tk.BooleanVar(value=False)
        self.title_checkbox = tk.Checkbutton(
            self.main,
            text="Videotitel als Kontext einbeziehen",
            variable=self.use_title_var,
            bg=CURRENT_THEME.BG_PRIMARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            selectcolor=CURRENT_THEME.BG_TERTIARY,
            activebackground=CURRENT_THEME.BG_HOVER,
            state="normal" if self.stream_title else "disabled"
        )
        self.title_checkbox.pack(anchor="w", pady=5)

        if not self.stream_title:
            ToolTip(self.title_checkbox, "Kein Titel verfügbar (z.B. bei lokalen Dateien)")
        else:
            self.title_checkbox.bind("<ButtonRelease-1>", lambda e: self._set_default_prompt())

        # 5. Prompt-Textfeld (editierbar)
        tk.Label(self.main, text="Prompt (optional):", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(anchor="w", pady=(10,2))
        self.prompt_text = scrolledtext.ScrolledText(
            self.main, height=4,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.MONOSPACE, wrap=tk.WORD
        )
        self.prompt_text.pack(fill="x", pady=(0,10))
        self._set_default_prompt()
        ToolTip(self.prompt_text, "Optionaler Prompt – wird an das Modell gesendet")

        # 6. Ausgabe der Zusammenfassung
        tk.Label(self.main, text="Zusammenfassung:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(anchor="w")
        self.summary_text = scrolledtext.ScrolledText(
            self.main, height=10,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.MONOSPACE, wrap=tk.WORD
        )
        self.summary_text.pack(fill="both", expand=True, pady=10)
        ContextMenuMixin(self.summary_text)

        # 7. Button-Leiste
        btn_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x", pady=5)

        btn_row1 = tk.Frame(btn_frame, bg=CURRENT_THEME.BG_PRIMARY)
        btn_row1.pack(fill="x", pady=2)
        self.summarize_btn = tk.Button(
            btn_row1, text="🤖 Zusammenfassen",
            command=self.start_summarize,
            bg=CURRENT_THEME.DRAGON_GREEN,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15
        )
        self.summarize_btn.pack(side="left", padx=5)

        self.cancel_btn = tk.Button(
            btn_row1, text="⏹️ Abbrechen",
            command=self.cancel_request,
            bg=CURRENT_THEME.ERROR,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15,
            state="disabled"
        )
        self.cancel_btn.pack(side="left", padx=5)

        self.copy_btn = tk.Button(
            btn_row1, text="📋 Kopieren",
            command=self.copy_summary,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15,
            state="disabled"
        )
        self.copy_btn.pack(side="left", padx=5)

        btn_row2 = tk.Frame(btn_frame, bg=CURRENT_THEME.BG_PRIMARY)
        btn_row2.pack(fill="x", pady=2)
        self.save_btn = tk.Button(
            btn_row2, text="💾 Speichern",
            command=self.save_summary,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15,
            state="disabled"
        )
        self.save_btn.pack(side="left", padx=5)

        self.translate_btn = tk.Button(
            btn_row2, text="🌐 Übersetzen",
            command=self.translate_summary,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15,
            state="disabled"
        )
        self.translate_btn.pack(side="left", padx=5)

        self.close_btn = tk.Button(
            btn_row2, text="Schließen",
            command=self.close,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON, padx=15
        )
        self.close_btn.pack(side="left", padx=5)

        # 8. Statuszeile
        self.status_label = tk.Label(
            self.main, text="", bg=CURRENT_THEME.BG_PRIMARY,
            fg=CURRENT_THEME.TEXT_SECONDARY, font=Fonts.SMALL
        )
        self.status_label.pack(pady=5)

        # Interne Variablen für die Verarbeitung
        self.full_summary = ""

    # -------------------------------------------------------------------------
    # Interne Hilfsmethoden
    # -------------------------------------------------------------------------
    def _set_default_prompt(self) -> None:
        """Setzt den Standard-Prompt basierend auf der ausgewählten Sprache und dem Videotitel."""
        target = self.summary_lang_var.get()
        if target == "Deutsch":
            prompt = (
                "Fasse den folgenden Text in 3-5 Sätzen auf Deutsch zusammen. "
                "Konzentriere dich auf die Hauptaussagen, ignoriere Wiederholungen und Füllwörter. "
                "Verwende vollständige, idiomatische Sätze.\n\n"
                "WICHTIG: Die Ausgabe MUSS auf DEUTSCH erfolgen und darf KEINE Zeichen aus anderen "
                "Sprachen (wie Chinesisch, Japanisch oder Koreanisch) enthalten. "
                "Fachbegriffe wie 'Sakura' oder 'Kimchi' können als Lehnwörter verwendet werden, "
                "aber bitte in lateinischer Schrift.\n\n"
                "Achte darauf, dass Begriffe, die im Deutschen mehrere Bedeutungen haben könnten (z.B. ‚Verhältnis‘), "
                "im jeweiligen Zusammenhang eindeutig sind. Wähle stattdessen präzisere Ausdrücke."
            )
        elif target == "Englisch":
            prompt = (
                "Summarize the following text in 3-5 sentences in English. "
                "Focus on the main points, ignore repetitions and filler words. "
                "Use complete, idiomatic sentences.\n\n"
                "IMPORTANT: The output MUST be in ENGLISH and must NOT contain characters from other "
                "languages (like Chinese, Japanese, or Korean). Loanwords are acceptable in Latin script."
            )
        elif target == "Spanisch":
            prompt = (
                "Resume el siguiente texto en 3-5 oraciones en español. "
                "Concéntrate en las ideas principales, ignora repeticiones y palabras de relleno. "
                "Utiliza oraciones completas e idiomáticas.\n\n"
                "IMPORTANTE: La salida DEBE estar en ESPAÑOL y NO debe contener caracteres de otros "
                "idiomas (como chino, japonés o coreano). Los préstamos son aceptables en escritura latina."
            )
        elif target == "Koreanisch":
            prompt = (
                "다음 텍스트를 한국어로 3-5문장으로 요약하세요. "
                "핵심 내용에 집중하고, 반복과 불용어는 무시하세요. "
                "완전하고 관용적인 문장을 사용하세요.\n\n"
                "중요: 출력은 반드시 한국어로 작성되어야 하며 다른 언어(예: 중국어, 일본어)의 문자가 포함되어서는 안 됩니다. "
                "외래어는 라틴 문자로 표기해도 됩니다."
            )
        elif target == "Chinesisch":
            prompt = (
                "将以下文本用中文总结成3-5句话。专注于主要观点，忽略重复和填充词。"
                "使用完整、地道的句子。\n\n"
                "重要：输出必须是中文，不能包含其他语言的字符。外来词可以用拉丁字母表示。"
            )
        else:
            prompt = (
                f"Summarize the following text in 3-5 sentences in {target}. "
                f"Focus on the main points, ignore repetitions and filler words. "
                f"Use complete, idiomatic sentences.\n\n"
                f"IMPORTANT: The output MUST be in {target.upper()} and must NOT contain characters from other languages."
            )

        if self.use_title_var.get() and self.stream_title:
            title_prefix = f"Der Titel des Videos lautet: '{self.stream_title}'.\n\n"
        else:
            title_prefix = ""

        full_prompt = title_prefix + prompt
        self.prompt_text.delete("1.0", "end")
        self.prompt_text.insert("1.0", full_prompt)

    def _split_text(self, text: str, max_words: int = 2000) -> List[str]:
        """
        Teilt einen langen Text in mehrere Chunks auf, basierend auf der Wortanzahl.

        Args:
            text: Der zu teilende Text.
            max_words: Maximale Anzahl von Wörtern pro Chunk.

        Returns:
            Liste von Text-Chunks.
        """
        words = text.split()
        if len(words) <= max_words:
            return [text]
        chunks = []
        chunk = []
        word_count = 0
        for word in words:
            chunk.append(word)
            word_count += 1
            if word_count >= max_words:
                chunks.append(" ".join(chunk))
                chunk = []
                word_count = 0
        if chunk:
            chunks.append(" ".join(chunk))
        return chunks

    def _process_next_chunk(self, retry_count: int = 0) -> None:
        """
        Verarbeitet den nächsten Text-Chunk (für große Texte).

        Args:
            retry_count: Anzahl bisheriger Wiederholungsversuche.
        """
        if self._destroyed or self._request_cancel.is_set():
            self._create_final_summary()
            return

        if self._current_chunk >= len(self._chunks):
            self._create_final_summary()
            return

        chunk_text = self._chunks[self._current_chunk]
        self.status_label.config(
            text=f"⏳ Verarbeite Abschnitt {self._current_chunk+1}/{len(self._chunks)}... (Versuch {retry_count+1})"
        )

        def on_chunk_complete():
            if self.summarizer.last_result:
                self._chunk_results.append(self.summarizer.last_result)
            else:
                self._chunk_results.append("")
            self._current_chunk += 1
            self._safe_after(100, lambda: self._process_next_chunk(0))

        def on_chunk_error(error: str):
            if retry_count < 3:
                delay_ms = 1000 * (2 ** retry_count)
                self.status_label.config(
                    text=f"⏳ Fehler, Wiederholung in {delay_ms//1000}s... (Versuch {retry_count+2}/4)"
                )
                self._safe_after(delay_ms, lambda: self._process_next_chunk(retry_count + 1))
            else:
                error_msg = f"[Fehler in Abschnitt {self._current_chunk+1} nach 3 Versuchen: {error}]"
                self._chunk_results.append(error_msg)
                self.status_label.config(
                    text=f"❌ Abschnitt {self._current_chunk+1} fehlgeschlagen – fahre mit nächstem fort"
                )
                self._current_chunk += 1
                self._safe_after(100, lambda: self._process_next_chunk(0))

        self.summarizer.summarize(
            chunk_text,
            self._prompt,
            self._temp,
            callback=lambda chunk: None,  # bei Chunks keine Einzelausgaben, nur Gesamtergebnis
            error_callback=on_chunk_error,
            complete_callback=on_chunk_complete,
            cancel_event=self._request_cancel,
        )

    def _create_final_summary(self) -> None:
        """
        Erstellt aus den einzelnen Chunk-Ergebnissen eine finale Zusammenfassung.
        """
        if not self._chunk_results:
            self.status_label.config(text="❌ Keine Teilzusammenfassungen vorhanden.")
            self._reset_ui()
            return

        valid_chunks = [res for res in self._chunk_results if res and not res.startswith("[Fehler")]
        if not valid_chunks:
            self.status_label.config(text="❌ Keine gültigen Teilzusammenfassungen.")
            self._reset_ui()
            return

        combined = "\n\n".join(valid_chunks)
        target_lang = self.summary_lang_var.get()
        final_prompt = (f"Fasse die folgenden Teilzusammenfassungen zu einer kohärenten Gesamtzusammenfassung in {target_lang} zusammen. "
                        f"Antworte ausschließlich auf {target_lang}.\n\n{combined}")

        self.status_label.config(text="⏳ Erstelle finale Zusammenfassung...")

        def on_final_complete():
            if self._destroyed:
                return
            if self.dialog and self.dialog.winfo_exists():
                self._safe_after(0, self._reset_ui)

        self.summarizer.summarize(
            combined,
            final_prompt,
            self._temp,
            callback=self.on_chunk,
            error_callback=self.on_error,
            complete_callback=on_final_complete,
            cancel_event=self._request_cancel,
        )

    def _reset_ui(self) -> None:
        """
        Setzt die UI nach Abschluss oder Abbruch zurück (Buttons aktivieren, Status löschen).
        """
        if self._destroyed:
            return
        try:
            if self.dialog and self.dialog.winfo_exists():
                self.summarize_btn.config(state="normal", text="🤖 Zusammenfassen")
                self.cancel_btn.config(state="disabled")
                self.copy_btn.config(state="normal" if self.full_summary else "disabled")
                self.save_btn.config(state="normal" if self.full_summary else "disabled")
                self.translate_btn.config(state="normal" if self.full_summary else "disabled")
                self.status_label.config(text="✅ Zusammenfassung abgeschlossen")

                # Optional: Blacklist-Prüfung und Sprachvalidierung
                if self.full_summary and hasattr(self.gui, "advanced_settings"):
                    blacklist = getattr(self.gui.advanced_settings, "blacklist", [])
                    found = []
                    for phrase in blacklist:
                        if phrase and phrase.lower() in self.full_summary.lower():
                            found.append(phrase)
                    if found:
                        logger.warning(f"Zusammenfassung enthält Blacklist-Phrasen: {found}")
                        self.status_label.config(
                            text=f"⚠️ Warnung: Blacklist-Phrasen gefunden: {', '.join(found[:2])}"
                        )
        except tk.TclError:
            pass

    # -------------------------------------------------------------------------
    # Öffentliche Callback-Methoden (werden von OllamaSummarizer aufgerufen)
    # -------------------------------------------------------------------------
    def on_chunk(self, chunk: str) -> None:
        """
        Wird bei jedem eingehenden Teil der Zusammenfassung aufgerufen.

        Args:
            chunk: Ein Teilstring der Antwort.
        """
        if self._destroyed:
            return

        def update():
            if self._destroyed:
                return
            try:
                if self.dialog and self.dialog.winfo_exists():
                    if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                        self.summary_text.insert("end", chunk)
                        self.summary_text.see("end")
                        self.full_summary += chunk
            except tk.TclError:
                pass

        self._safe_after(0, update)

    def on_error(self, error: str) -> None:
        """
        Wird bei einem Fehler während der Zusammenfassung aufgerufen.

        Args:
            error: Fehlermeldung.
        """
        if self._destroyed:
            return

        def update():
            if self._destroyed:
                return
            try:
                if self.dialog and self.dialog.winfo_exists():
                    if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                        self.summary_text.delete("1.0", "end")
                        self.summary_text.insert("1.0", f"Fehler: {error}")
                    self._reset_ui()
                    if hasattr(self, "status_label") and self.status_label.winfo_exists():
                        self.status_label.config(text="❌ Fehler")
            except tk.TclError:
                pass

        self._safe_after(0, update)

    # -------------------------------------------------------------------------
    # Benutzeraktionen
    # -------------------------------------------------------------------------
    def start_summarize(self) -> None:
        """Startet die Zusammenfassung."""
        if self._destroyed:
            return

        # Erneute Prüfung der Server‑Verfügbarkeit, falls zwischenzeitlich Probleme auftraten
        if not self.summarizer.is_server_reachable():
            self.status_label.config(text="❌ Ollama-Server nicht erreichbar. Bitte starte 'ollama serve'.")
            return

        model = self.model_var.get().strip()
        if model == "--- Modell auswählen ---" or model.startswith("(keine"):
            self.status_label.config(text="❌ Bitte ein gültiges Modell auswählen")
            return

        if not self.summarizer.is_model_available(model):
            self.status_label.config(text=f"❌ Modell '{model}' nicht auf Server gefunden.")
            return

        # Konfiguration aktualisieren
        self.summarizer.model = model
        self.summarizer.host = self.gui.advanced_settings.ollama_host
        target_lang = self.summary_lang_var.get()
        system_prompt = f"Du bist ein Assistent, der Texte auf {target_lang} zusammenfasst. Antworte ausschließlich auf {target_lang}."
        self.summarizer.system_prompt = system_prompt
        self._prompt = self.prompt_text.get("1.0", "end-1c").strip()
        self._temp = self.temp_var.get()

        # Text aufteilen, falls zu lang
        word_count = len(self.text.split())
        if word_count > 2000:
            self.status_label.config(text="⏳ Text wird in Abschnitte zerlegt...")
            self.summarize_btn.config(state="disabled", text="⏳ Warte...")
            self.cancel_btn.config(state="normal")
            self.copy_btn.config(state="disabled")
            self.save_btn.config(state="disabled")
            self.translate_btn.config(state="disabled")
            self._request_cancel.clear()
            self.full_summary = ""
            self.summary_text.delete("1.0", "end")
            chunks = self._split_text(self.text, max_words=2000)
            self.status_label.config(text=f"⏳ Verarbeite {len(chunks)} Abschnitte...")
            self._chunks = chunks
            self._chunk_results = []
            self._current_chunk = 0
            self._process_next_chunk()
        else:
            self.summarize_btn.config(state="disabled", text="⏳ Warte...")
            self.cancel_btn.config(state="normal")
            self.copy_btn.config(state="disabled")
            self.save_btn.config(state="disabled")
            self.translate_btn.config(state="disabled")
            self.status_label.config(text="Sende Anfrage an Ollama...")
            self.summary_text.delete("1.0", "end")
            self.full_summary = ""
            self._request_cancel.clear()

            def on_complete() -> None:
                if self._destroyed:
                    return
                if self.dialog and self.dialog.winfo_exists():
                    self._safe_after(0, self._reset_ui)

            self.summarizer.summarize(
                self.text,
                self._prompt,
                self._temp,
                callback=self.on_chunk,
                error_callback=self.on_error,
                complete_callback=on_complete,
                cancel_event=self._request_cancel,
            )

    def cancel_request(self) -> None:
        """Bricht die laufende Zusammenfassung ab."""
        self._request_cancel.set()
        self.status_label.config(text="⏹️ Abbruch eingeleitet...")
        self.cancel_btn.config(state="disabled")
        self._safe_after(500, self._reset_ui)

    def copy_summary(self) -> None:
        """Kopiert die Zusammenfassung in die Zwischenablage."""
        if self._destroyed:
            return
        try:
            if self.dialog and self.dialog.winfo_exists():
                if self.full_summary:
                    self.dialog.clipboard_clear()
                    self.dialog.clipboard_append(self.full_summary)
                    self.status_label.config(text="✅ In Zwischenablage kopiert")
                else:
                    self.status_label.config(text="⚠️ Keine Zusammenfassung vorhanden")
        except tk.TclError:
            pass

    def save_summary(self) -> None:
        """Speichert die Zusammenfassung als Textdatei."""
        if not self.full_summary:
            self.status_label.config(text="⚠️ Keine Zusammenfassung zum Speichern")
            return
        from tkinter import filedialog
        filename = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Textdateien", "*.txt"), ("Alle Dateien", "*.*")],
            title="Zusammenfassung speichern",
        )
        if filename:
            try:
                with open(filename, "w", encoding="utf-8") as f:
                    f.write(self.full_summary)
                self.status_label.config(text=f"💾 Gespeichert: {os.path.basename(filename)}")
            except Exception as e:
                self.status_label.config(text=f"❌ Fehler beim Speichern: {e}")

    def translate_summary(self) -> None:
        """Öffnet einen Übersetzungsdialog für die Zusammenfassung."""
        if not self.full_summary:
            self.status_label.config(text="⚠️ Keine Zusammenfassung zum Übersetzen")
            return
        if not hasattr(self.gui, "translation_engine"):
            self.status_label.config(text="❌ Keine Übersetzungs-Engine verfügbar")
            return
        engine = self.gui.translation_engine
        if hasattr(engine, "is_functional") and not engine.is_functional():
            self.status_label.config(text="⚠️ Übersetzungs-Engine derzeit nicht verfügbar")
            return
        TranslationDialog(self.dialog, engine, initial_text=self.full_summary)

    def close(self) -> None:
        """
        Schließt den Dialog und gibt Ressourcen frei.
        Stoppt die laufende Verarbeitung und speichert die Einstellungen.
        """
        # Einstellungen zurückschreiben
        if hasattr(self, 'temp_var') and hasattr(self, 'model_var'):
            self.gui.advanced_settings.summarize_temperature = self.temp_var.get()
            self.gui.advanced_settings.summarize_model = self.model_var.get()
            self.gui.advanced_settings.save_to_file()

        # Verarbeitung abbrechen
        self._request_cancel.set()
        if hasattr(self, 'summarizer'):
            try:
                self.summarizer.dispose()
            except Exception:
                pass

        self._destroyed = True
        super().close()


class TranslationDialog(BaseDialog):
    """
    Dialog zum Übersetzen von Text mit verschiedenen Übersetzungs‑Engines.

    Bietet:
    - Auswahl der Quell‑ und Zielsprache (nur lesbare Namen)
    - Auswahl der Übersetzungs‑Engine (Google, Ollama, Argos)
    - Parallele Übersetzung von Sätzen
    - Automatischer Fallback auf eine zweite Engine bei schlechter Qualität
    - Abbruchmöglichkeit während der Übersetzung
    - Saubere Ressourcenfreigabe beim Schließen
    """

    def __init__(self, parent: tk.Widget, translation_engine: BaseTranslationEngine, gui_ref: Any, initial_text: str = "") -> None:
        """
        Initialisiert den Übersetzungsdialog.

        Args:
            parent: Das übergeordnete Widget (i.d.R. das Hauptfenster).
            translation_engine: Die Standard‑Übersetzungs‑Engine (z.B. Google).
            initial_text: Text, der im Quellfeld vorausgefüllt wird.
        """
        self.engine = translation_engine
        self.gui = gui_ref
        self.initial_text = initial_text
        self._cancel_event = threading.Event()
        self.engine_var = tk.StringVar(value=self.engine.__class__.__name__.replace('TranslationEngine', '').lower())
        self._executor = ThreadPoolExecutor(max_workers=3, thread_name_prefix="TransDialog")
        self._executor_shutdown = False

        # Fallback‑Engine aus der GUI holen (falls vorhanden)
        self.fallback_engine: Optional[BaseTranslationEngine] = None
        if self.gui and hasattr(self.gui, 'audio_processor'):
            ap = self.gui.audio_processor
            if hasattr(ap, '_fallback_translation_engine') and ap._fallback_translation_engine:
                self.fallback_engine = ap._fallback_translation_engine
                # Zielsprache für Fallback setzen, sobald bekannt
                if hasattr(self.fallback_engine, 'set_target_language'):
                    self.fallback_engine.set_target_language(self.engine.default_target_lang)

        super().__init__(parent, "Text Translation", width=600, height=600, modal=True)

    def build_ui(self) -> None:
        """Erstellt die GUI-Elemente des Dialogs."""
        # Quelltext
        tk.Label(self.main, text="Source text:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY, font=Fonts.PRIMARY).pack(anchor="w")
        self.source_text = scrolledtext.ScrolledText(self.main, height=8,
                                                      bg=CURRENT_THEME.BG_TERTIARY,
                                                      fg=CURRENT_THEME.TEXT_PRIMARY,
                                                      font=Fonts.MONOSPACE, wrap=tk.WORD)
        self.source_text.pack(fill="x", pady=(0,10))
        if self.initial_text:
            self.source_text.insert("1.0", self.initial_text)
        ContextMenuMixin(self.source_text)

        # Sprachauswahl
        lang_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        lang_frame.pack(fill="x", pady=5)

        tk.Label(lang_frame, text="From:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left", padx=(0,5))
        self.src_lang_var = tk.StringVar(value="auto")
        src_combo = ttk.Combobox(lang_frame, textvariable=self.src_lang_var,
                                  values=["auto"] + [name for name, code in SORTED_LANGUAGES],
                                  width=15, state="readonly")
        src_combo.pack(side="left", padx=(0,20))
        ToolTip(src_combo, "Quellsprache (automatisch = Whisper-Erkennung)")

        tk.Label(lang_frame, text="To:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left", padx=(0,5))
        current_target_name = SUPPORTED_LANGUAGES.get(self.engine.default_target_lang, "Deutsch")
        self.tgt_lang_var = tk.StringVar(value=current_target_name)
        tgt_combo = ttk.Combobox(lang_frame, textvariable=self.tgt_lang_var,
                                  values=[name for name, code in SORTED_LANGUAGES if name != "auto"],
                                  width=15, state="readonly")
        tgt_combo.pack(side="left")
        ToolTip(tgt_combo, "Zielsprache für die Übersetzung")

        # Engine-Auswahl
        engine_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        engine_frame.pack(fill="x", pady=5)
        tk.Label(engine_frame, text="Engine:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY).pack(side="left", padx=(0,5))
        engine_combo = ttk.Combobox(engine_frame, textvariable=self.engine_var,
                                     values=["google", "ollama", "argos"],
                                     width=10, state="readonly")
        engine_combo.pack(side="left")
        ToolTip(engine_combo, "Übersetzungs-Engine auswählen (Google, Ollama, Argos)")

        # Steuerbuttons
        btn_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x", pady=10)

        self.translate_btn = tk.Button(btn_frame, text="🌐 Translate",
                                        command=self.translate,
                                        bg=CURRENT_THEME.DRAGON_GREEN,
                                        fg=CURRENT_THEME.TEXT_PRIMARY,
                                        font=Fonts.BUTTON, padx=20)
        self.translate_btn.pack(side="left")

        self.cancel_btn = tk.Button(btn_frame, text="⏹️ Cancel",
                                     command=self.cancel_translation,
                                     bg=CURRENT_THEME.ERROR,
                                     fg=CURRENT_THEME.TEXT_PRIMARY,
                                     font=Fonts.BUTTON, padx=20,
                                     state="disabled")
        self.cancel_btn.pack(side="left", padx=10)

        # Übersetzungsergebnis
        tk.Label(self.main, text="Translation:", bg=CURRENT_THEME.BG_PRIMARY,
                 fg=CURRENT_THEME.TEXT_PRIMARY, font=Fonts.PRIMARY).pack(anchor="w", pady=(10,0))
        self.target_text = scrolledtext.ScrolledText(self.main, height=8,
                                                       bg=CURRENT_THEME.BG_TERTIARY,
                                                       fg=CURRENT_THEME.TEXT_PRIMARY,
                                                       font=Fonts.MONOSPACE, wrap=tk.WORD,
                                                       state="normal")
        self.target_text.pack(fill="both", expand=True, pady=(5,0))
        ContextMenuMixin(self.target_text)

        self.progress_label = tk.Label(self.main, text="", bg=CURRENT_THEME.BG_PRIMARY,
                                        fg=CURRENT_THEME.TEXT_SECONDARY, font=Fonts.SMALL)
        self.progress_label.pack(pady=2)

        close_btn = tk.Button(self.main, text="Close", command=self.close,
                               bg=CURRENT_THEME.BG_TERTIARY,
                               fg=CURRENT_THEME.TEXT_PRIMARY)
        close_btn.pack(pady=10)

        self.source_text.focus_set()

    # ----- Hilfsmethoden -----
    def _split_sentences(self, text: str) -> List[str]:
        """Zerlegt einen Text in Sätze (einfache Implementierung mit Satzendzeichen)."""
        sentence_endings = r'(?<=[.!?。！？])\s+'
        sentences = re.split(sentence_endings, text)
        return [s.strip() for s in sentences if s.strip()]

    def _translate_one(self, sentence: str, src_code: str, engine: BaseTranslationEngine) -> str:
        """Übersetzt einen einzelnen Satz mit der angegebenen Engine."""
        try:
            result = engine.translate_text(sentence, src_code)
            if result and result.translated:
                return result.translated
            else:
                return sentence
        except Exception as e:
            logger.error(f"Fehler bei Übersetzung von Satz: {e}", exc_info=True)
            return sentence

    def _is_valid_translation(self, original: str, translated: str) -> bool:
        """Prüft, ob eine Übersetzung sinnvoll ist (nicht leer, nicht identisch, nicht zu viele Sonderzeichen)."""
        if not translated or len(translated) < 2:
            return False
        if translated.lower() == original.lower():
            return False
        # Nicht zu lange (maximal 10-fache Länge)
        if len(translated) > len(original) * 10:
            return False
        # Mindestens 20% Buchstaben (für nicht-asiatische Sprachen)
        alpha_ratio = sum(c.isalpha() for c in translated) / max(len(translated), 1)
        if alpha_ratio < 0.2 and len(translated) > 20:
            return False
        return True

    # ----- Hauptmethoden -----
    def translate(self) -> None:
        """Startet die Übersetzung des eingegebenen Textes."""
        source = self.source_text.get("1.0", "end-1c").strip()
        if not source:
            return

        src_name = self.src_lang_var.get().strip()
        tgt_name = self.tgt_lang_var.get().strip()
        engine_name = self.engine_var.get().strip()
        logger.debug(f"TranslationDialog: translate called with src='{src_name}', tgt='{tgt_name}', engine='{engine_name}'")

        # Sprachcodes aus Namen ermitteln
        valid_language_names = [name for name, code in SORTED_LANGUAGES]
        if src_name not in valid_language_names and src_name != "auto":
            src_name = "auto"
            self.src_lang_var.set("auto")
        if tgt_name not in valid_language_names:
            tgt_name = "Deutsch"
            self.tgt_lang_var.set("Deutsch")

        try:
            src_code = "auto" if src_name == "auto" else next(code for name, code in SORTED_LANGUAGES if name == src_name)
            tgt_code = next(code for name, code in SORTED_LANGUAGES if name == tgt_name)
        except StopIteration:
            self._display_error("Ungültige Sprachauswahl")
            return

        # Engine erstellen (entweder temporär oder vorhandene Engine anpassen)
        if self.gui and hasattr(self.gui, "_create_temporary_translation_engine"):
            engine = self.gui._create_temporary_translation_engine(engine_name, tgt_code)
            if engine is None:
                self._display_error(f"Engine '{engine_name}' nicht verfügbar")
                return
            fallback = self.fallback_engine
        else:
            engine = self.engine
            old_target = engine.default_target_lang
            engine.set_target_language(tgt_code)
            fallback = self.fallback_engine
            if fallback and hasattr(fallback, 'set_target_language'):
                fallback.set_target_language(tgt_code)

        # UI zurücksetzen
        self.translate_btn.config(state="disabled", text="⏳ Translating...")
        self.cancel_btn.config(state="normal")
        self.target_text.delete("1.0", "end")
        self.progress_label.config(text="")
        self._cancel_event.clear()

        # Sätze aufteilen
        sentences = self._split_sentences(source)
        total = len(sentences)
        if total == 0:
            self._reset_ui()
            return

        if total == 1:
            # Einzelner Satz: synchron übersetzen
            self._translate_single(sentences[0], src_code, engine, fallback,
                                   old_target if not self.gui else None)
        else:
            # Mehrere Sätze: parallel übersetzen
            self._translate_multi(sentences, src_code, engine, fallback,
                                  old_target if not self.gui else None)

    def _translate_single(self, text: str, src_code: str,
                          engine: BaseTranslationEngine, fallback: Optional[BaseTranslationEngine],
                          old_target: Optional[str]) -> None:
        """Übersetzt einen einzelnen Satz im Hintergrundthread mit Fallback bei schlechter Qualität."""
        def worker():
            try:
                # Primäre Engine
                result = engine.translate_text(text, src_code)
                translated = result.translated if result else None
                # Qualitätsprüfung
                if translated and not self._is_valid_translation(text, translated):
                    logger.debug(f"Primäre Übersetzung ungültig: '{translated[:50]}...'")
                    if fallback and fallback.is_functional():
                        logger.info("🔄 Versuche Fallback-Engine...")
                        fallback_result = fallback.translate_text(text, src_code)
                        if fallback_result and fallback_result.translated:
                            translated = fallback_result.translated
                            logger.info("✅ Fallback erfolgreich")
                        else:
                            translated = None
                if translated and not self._cancel_event.is_set():
                    self._display_result(translated)
                elif not self._cancel_event.is_set():
                    self._display_error("Übersetzung fehlgeschlagen")
            except Exception as e:
                if not self._cancel_event.is_set():
                    self._display_error(str(e))
            finally:
                if not self.gui and old_target is not None:
                    engine.set_target_language(old_target)
                if not self._cancel_event.is_set():
                    self._reset_ui()
        self._executor.submit(worker)

    def _translate_multi(self, sentences: List[str], src_code: str,
                         engine: BaseTranslationEngine, fallback: Optional[BaseTranslationEngine],
                         old_target: Optional[str]) -> None:
        """Übersetzt mehrere Sätze parallel und sammelt die Ergebnisse, mit Fallback bei schlechten Sätzen."""
        translated_sentences = [None] * len(sentences)
        futures = []
        for i, sentence in enumerate(sentences):
            # Übersetzung mit primärer Engine
            future = self._executor.submit(self._translate_one, sentence, src_code, engine)
            futures.append((i, future))

        def collect_results():
            # Primäre Ergebnisse sammeln und ggf. Fallback für schlechte
            for i, future in futures:
                if self._cancel_event.is_set():
                    break
                try:
                    result = future.result()
                    # Qualitätsprüfung
                    if not self._is_valid_translation(sentences[i], result):
                        if fallback and fallback.is_functional():
                            logger.debug(f"Satz {i} ungültig, verwende Fallback")
                            fallback_result = fallback.translate_text(sentences[i], src_code)
                            if fallback_result and fallback_result.translated:
                                result = fallback_result.translated
                            else:
                                result = sentences[i]  # Fallback: Original beibehalten
                    translated_sentences[i] = result
                except Exception as e:
                    logger.error(f"Fehler bei Übersetzung von Satz {i}: {e}")
                    translated_sentences[i] = sentences[i]
            full_translation = " ".join(translated_sentences)
            if not self._cancel_event.is_set():
                self.dialog.after(0, self._display_result, full_translation)
                self.dialog.after(0, self._reset_ui)

        threading.Thread(target=collect_results, daemon=True).start()

    def _display_result(self, translated_text: str) -> None:
        """Zeigt das Übersetzungsergebnis im GUI an."""
        if self.dialog and self.dialog.winfo_exists():
            self.target_text.delete("1.0", "end")
            self.target_text.insert("1.0", translated_text)

    def _display_error(self, error: str) -> None:
        """Zeigt einen Fehler im Ergebnisbereich an."""
        if self.dialog and self.dialog.winfo_exists():
            self.target_text.delete("1.0", "end")
            self.target_text.insert("1.0", f"Error: {error}")

    def _reset_ui(self) -> None:
        """Setzt die Buttons und die Statusanzeige zurück."""
        if self.dialog and self.dialog.winfo_exists():
            self.translate_btn.config(state="normal", text="🌐 Translate")
            self.cancel_btn.config(state="disabled")
            self.progress_label.config(text="")

    def cancel_translation(self) -> None:
        """Bricht die laufende Übersetzung ab."""
        self._cancel_event.set()
        self._reset_ui()
        self.target_text.insert("1.0", "(Translation cancelled)")

    def close(self) -> None:
        """
        Schließt den Dialog und gibt alle Ressourcen frei.
        Stellt sicher, dass der ThreadPoolExecutor heruntergefahren wird.
        """
        self._cancel_event.set()
        if not self._executor_shutdown:
            self._executor_shutdown = True
            try:
                self._executor.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
        super().close()


class ShortcutsDialog(BaseDialog):
    def __init__(self, parent):
        super().__init__(parent, "Tastenkürzel", width=500, height=400, modal=True)

    def build_ui(self) -> None:
        tk.Label(self.main, text="Tastenkürzel", font=("Segoe UI", 14, "bold"),
                 bg=CURRENT_THEME.BG_PRIMARY, fg=CURRENT_THEME.TEXT_PRIMARY).pack(pady=(0,15))
        mod = "Cmd" if IS_MACOS else "Strg"
        shortcuts = [
            (f"{mod}+O", "Datei öffnen"),
            (f"{mod}+V", "URL einfügen"),
            (f"{mod}+Return", "Transkription starten"),
            (f"{mod}+Q", "Programm beenden"),
            (f"{mod}+S", "Transkript speichern"),
            (f"{mod}+L", "Layout umschalten"),
            (f"{mod}+T", "Übersetzung ein/aus"),
            (f"{mod}+E", "Untertitel exportieren"),
            (f"{mod}+Umschalt+C", "Alles löschen"),
            ("F1", "Diese Hilfe anzeigen"),
        ]
        frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_SECONDARY)
        frame.pack(fill="both", expand=True)
        for i, (key, desc) in enumerate(shortcuts):
            row = tk.Frame(frame, bg=CURRENT_THEME.BG_TERTIARY if i % 2 else CURRENT_THEME.BG_SECONDARY)
            row.pack(fill="x", pady=1)
            key_label = tk.Label(row, text=key, font=("Segoe UI", 10, "bold"),
                                  bg=row["bg"], fg=CURRENT_THEME.TEXT_ACCENT,
                                  width=15, anchor="w")
            key_label.pack(side="left", padx=(10,5), pady=5)
            desc_label = tk.Label(row, text=desc, font=("Segoe UI", 10),
                                   bg=row["bg"], fg=CURRENT_THEME.TEXT_PRIMARY,
                                   anchor="w")
            desc_label.pack(side="left", fill="x", expand=True, padx=5, pady=5)
        close_btn = tk.Button(self.main, text="Schließen", command=self.close,
                               bg=CURRENT_THEME.BG_TERTIARY,
                               fg=CURRENT_THEME.TEXT_PRIMARY)
        close_btn.pack(pady=10)


