    def _on_translation_language_changed(self, lang_display: str) -> None:
        """Aktualisiert die Überschrift des Übersetzungs‑Bereichs."""
        def update():
            self._safe_widget_config("translation_header", text=f"🌐 Übersetzung ({lang_display})")
